1	/**
2	 * Orchestrator main entry point.
3	 *
4	 * Lifecycle:
5	 *   bootstrap (once) → polling loop:
6	 *     pull workspaces → eligibility → claim → briefing → adapter.run →
7	 *     side-effects → sleep → repeat
8	 *
9	 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
10	 *   0   → single-shot mode: one cycle then exit
11	 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
12	 *
13	 * Exit codes:
14	 *   0  normal exit
15	 *   2  agent.yaml invalid
16	 *   3  git clone/pull failed (bootstrap only)
17	 *   4  unexpected fatal error
18	 */
19	
20	import { existsSync, readFileSync, writeFileSync } from "node:fs";
21	import { join } from "node:path";
22	import { tmpdir } from "node:os";
23	import { execSync, spawn } from "node:child_process";
24	import { randomUUID } from "node:crypto";
25	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
26	import { runBootstrap } from "./bootstrap/bootstrap.js";
27	import { resolveSSHKey } from "./resolve-ssh-key.js";
28	import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "./paths.js";
29	import { findEligibleTasks } from "./eligibility/match.js";
30	import { claimTask } from "./claim/claim-task.js";
31	import { openWorkspacePr } from "./claim/open-workspace-pr.js";
32	import type { Task, TaskLogEntry } from "./types/task.js";
33	import { generateBriefing } from "./briefing/agent-context.js";
34	import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
35	import { resolveModel } from "./config/resolve-model-policy.js";
36	import { parseModelOverrides } from "./config/parse-model-overrides.js";
37	import {
38	  resolveRepoLocalPath,
39	  resolveRepoBaseBranch,
40	  resolveRepoGitUrl,
41	  loadWorkspaceModelPolicy,
42	  parseManagementRepoCoords,
43	} from "./config/workspace-config.js";
44	import { pullWorkspaces } from "./poll/pull-workspaces.js";
45	import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
46	import { runReapLoop } from "./poll/reap-loop.js";
47	import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
48	import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
49	import { handleDraftReviews } from "./pr-response/dispatch-draft-review.js";
50	import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
51	import type { ExecutorPortInput } from "@workflow/runtime-abi";
52	import { buildGitEnv } from "./git-env.js";
53	import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
54	import { createLocalSubprocessProfile } from "./profiles/local-subprocess.js";
55	import { createLocalDockerProfile } from "./profiles/local-docker.js";
56	import type { RuntimePorts } from "./runtime-ports.js";
57	import { SubProcessAdapter } from "./adapters/executor/subprocess.js";
58	import { InMemoryBrokerAdapter } from "./adapters/broker/in-memory.js";
59	
60	// ── Helpers ───────────────────────────────────────────────────────────────────
61	
62	/**
63	 * Returns an invokeClaudeForResolution function that pins Claude to a specific model.
64	 * Passed to all conflict-resolution handlers so they respect workspace model_policy
65	 * instead of defaulting to whatever the Claude CLI ships with.
66	 */
67	function makeConflictResolver(
68	  model: string,
69	  maxTurns = 10,
70	): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
71	  return (prompt, cwd, env) =>
72	    new Promise((resolve) => {
73	      const child = spawn(
74	        "claude",
75	        [
76	          "-p", prompt,
77	          "--model", model,
78	          "--max-turns", String(maxTurns),
79	          "--output-format", "stream-json",
80	          "--verbose",
81	          "--dangerously-skip-permissions",
82	        ],
83	        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
84	      );
85	      child.stdout.pipe(process.stdout);
86	      child.stderr.pipe(process.stderr);
87	      child.on("close", (code) => resolve(code === 0));
88	      child.on("error", () => resolve(false));
89	    });
90	}
91	
92	function requireEnv(name: string): string {
93	  const val = process.env[name];
94	  if (!val) throw new Error(`Required environment variable ${name} is not set`);
95	  return val;
96	}
97	
98	function extractRepoName(url: string): string {
99	  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
100	  return match?.[1] ?? url;
101	}
102	
103	/** Emit a structured JSON event via the profile's EventEmitterPort. */
104	function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
105	  return (event: Record<string, unknown>) => {
106	    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
107	    ports.emitter.emit(type ?? "event", data);
108	  };
109	}
110	
111	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
112	  const task = parseYaml(
113	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
114	  ) as { repo: string };
115	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
116	  return task.repo;
117	}
118	
119	interface TaskContext {
120	  taskRepoRoot: string;
121	  taskRepoUrl: string;
122	  taskBaseBranch: string;
123	  implementationModel: string;
124	}
125	
126	function resolveTaskContext(
127	  workspaceLocalPath: string,
128	  featureId: string,
129	  task: Task,
130	): TaskContext {
131	  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
132	  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
133	  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
134	  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
135	
136	  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
137	  let taskModelOverrides = {};
138	  try {
139	    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
140	  } catch { /* non-fatal */ }
141	
142	  const implementationModel = resolveModel(
143	    workspaceModelPolicy,
144	    taskModelOverrides,
145	    "implementation",
146	    task.id,
147	  );
148	
149	  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
150	}
151	
152	/**
153	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
154	 * Commits and pushes to the task branch. Throws on error.
155	 */
156	function writeRagPreFlight(
157	  workspaceRoot: string,
158	  featureId: string,
159	  taskId: string,
160	  taskBranch: string,
161	  gitAuthorEmail: string,
162	  gitAuthorName: string,
163	  sshKeyPath: string | undefined,
164	  ragPreFlight: { query: string; injected: boolean; summary: string },
165	): void {
166	  const now = new Date().toISOString();
167	  const entry: TaskLogEntry = {
168	    action: "rag_pre_flight",
169	    by: gitAuthorEmail,
170	    at: now,
171	    rag_context_injected: ragPreFlight.injected,
172	    rag_summary: ragPreFlight.summary,
173	    rag_query: ragPreFlight.query,
174	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
175	  };
176	
177	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
178	  const relPath = taskYamlRelPath(featureId, taskId);
179	  const gitOpts = {
180	    cwd: workspaceRoot,
181	    encoding: "utf-8" as const,
182	    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
183	    timeout: 30_000,
184	    stdio: "pipe" as const,
185	  };
186	
187	  // Anchor to the task branch tip before reading/writing — same pattern as
188	  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
189	  // the task branch, but an explicit anchor makes this function self-contained.
190	  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
191	  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);
192	
193	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
194	  task.log.push(entry);
195	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
196	
197	  execSync(`git add "${relPath}"`, gitOpts);
198	  execSync(
199	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
200	    gitOpts,
201	  );
202	  execSync(`git push origin "${taskBranch}"`, gitOpts);
203	}
204	
205	// ── Main ──────────────────────────────────────────────────────────────────────
206	
207	async function main(): Promise<number> {
208	  let agentYamlPath: string;
209	  let workflowLocalPath: string;
210	  let workspacesRoot: string;
211	  let gitAuthorEmail: string;
212	
213	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
214	  const bootstrapEmit = (event: Record<string, unknown>) => {
215	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
216	  };
217	
218	  try {
219	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
220	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
221	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
222	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
223	  } catch (e) {
224	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
225	    return 4;
226	  }
227	
228	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
229	
230	  const sshResolution = resolveSSHKey(process.env);
231	  const sshKeyPath = sshResolution.sshKeyPath;
232	
233	  // ── Create the runtime profile ────────────────────────────────────────────────
234	  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
235	  // new infra is added without core changes.
236	  //   local-subprocess (default) — executor + in-process broker in one container
237	  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
238	  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
239	  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
240	    runtimeProfile === "local-docker"
241	      ? createLocalDockerProfile({
242	          gitAuthorEmail,
243	          gitAuthorName,
244	          sshKeyPath,
245	          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
246	        })
247	      : createLocalSubprocessProfile({
248	          gitAuthorEmail,
249	          gitAuthorName,
250	          sshKeyPath,
251	        });
252	
253	  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
254	  const brokerPort = await ports.broker.start();
255	
256	  const emit = makeEmit(ports);
257	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
258	
259	  if (sshResolution.warned) {
260	    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
261	  }
262	
263	  const bootstrapResult = await runBootstrap({
264	    agentYamlPath,
265	    workflowLocalPath,
266	    workflowUrl: process.env.WORKFLOW_URL,
267	    workspacesRoot,
268	    sshKeyPath,
269	  });
270	
271	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
272	
273	  const config = bootstrapResult.config!;
274	  const githubToken = process.env.GITHUB_TOKEN ?? "";
275	  if (!githubToken) emit({ type: "warn_no_github_token" });
276	
277	  let lastPrPollAt: number | null = null;
278	  // Local counter for local-docker mode — tracks how many executor containers are
279	  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
280	  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
281	  let dockerInFlight = 0;
282	
283	  async function runOneCycle(): Promise<CycleOutcome> {
284	    const pullResults = pullWorkspaces({
285	      watchUrls: config.watches,
286	      sshKeyPath,
287	      workspacesRoot,
288	      workflowUrl: process.env.WORKFLOW_URL,
289	      workflowLocalPath,
290	      emit,
291	    });
292	
293	    const haltedUrls = new Set(
294	      pullResults
295	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
296	        .map((r) => r.url),
297	    );
298	
299	    let outcome: CycleOutcome = "idle";
300	    const pulledWorkspaceRoots: string[] = [];
301	
302	    // ── Subprocess concurrency guard + task dispatch ──────────────────────────
303	    // In local-subprocess mode all repos share the same container filesystem.
304	    // Two concurrent subprocesses can race on git checkouts in the same repo.
305	    // Wrap the dispatch loop in a labeled block so we can break out of it
306	    // (skipping to PR poll + reap) when a subprocess is already in-flight.
307	    dispatchBlock: {
308	      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
309	      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;
310	
311	      if (runtimeProfile === "local-subprocess") {
312	        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
313	        if (inFlight >= maxConcurrent) {
314	          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
315	          break dispatchBlock;
316	        }
317	      } else if (runtimeProfile === "local-docker") {
318	        if (dockerInFlight >= maxConcurrent) {
319	          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
320	          break dispatchBlock;
321	        }
322	      }
323	
324	    outerLoop:
325	    for (const watchUrl of config.watches) {
326	      if (haltedUrls.has(watchUrl)) continue;
327	
328	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
329	      pulledWorkspaceRoots.push(workspaceLocalPath);
330	
331	      if (!existsSync(workspaceLocalPath)) {
332	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
333	        continue;
334	      }
335	
336	      let eligibleTasks;
337	      try {
338	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
339	      } catch (e) {
340	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
341	        continue;
342	      }
343	
344	      if (eligibleTasks.length === 0) {
345	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
346	        continue;
347	      }
348	
349	      for (const { task, featureId } of eligibleTasks) {
350	        const claimResult = await claimTask({
351	          workspaceRoot: workspaceLocalPath,
352	          taskId: task.id,
353	          featureId,
354	          gitAuthorEmail,
355	          gitAuthorName,
356	          sshKeyPath,
357	          jitterMaxSeconds: config.jitter_max_seconds,
358	        });
359	
360	        const taskBranch = taskBranchName(featureId, task.id);
361	
362	        if (!claimResult.won) {
363	          if (claimResult.reason !== "branch_blocked_recovery") {
364	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
365	            continue;
366	          }
367	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
368	        } else {
369	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
370	        }
371	
372	        // ── Open management-repo PR ───────────────────────────────────────────
373	        if (githubToken) {
374	          try {
375	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
376	            await openWorkspacePr({
377	              workspaceRoot: workspaceLocalPath,
378	              featureId,
379	              taskId: task.id,
380	              branch: taskBranch,
381	              baseBranch: mgmtCoords.baseBranch,
382	              githubToken,
383	              repoOwner: mgmtCoords.owner,
384	              repoName: mgmtCoords.repo,
385	              gitAuthorEmail,
386	              gitAuthorName,
387	              sshKeyPath,
388	            });
389	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
390	          } catch (e) {
391	            const stderr = (e as { stderr?: Buffer | string }).stderr;
392	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
393	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
394	          }
395	        }
396	
397	        // ── Resolve model + task repo ────────────────────────────────────────
398	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
399	          resolveTaskContext(workspaceLocalPath, featureId, task);
400	
401	        // ── RAG pre-flight ───────────────────────────────────────────────────
402	        const mcpRagUrl = process.env.MCP_RAG_URL;
403	        const workspaceYaml = parseYaml(
404	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
405	        ) as { workspace_id: string };
406	        const ragQuery = `${task.title} ${featureId}`;
407	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
408	
409	        try {
410	          writeRagPreFlight(
411	            workspaceLocalPath,
412	            featureId,
413	            task.id,
414	            taskBranch,
415	            gitAuthorEmail,
416	            gitAuthorName,
417	            sshKeyPath,
418	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
419	          );
420	        } catch (e) {
421	          const details = String(e);
422	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
423	          mutateTaskYaml({
424	            workspaceRoot: workspaceLocalPath,
425	            featureId,
426	            taskId: task.id,
427	            taskBranch,
428	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
429	            gitAuthorEmail,
430	            gitAuthorName,
431	            sshKeyPath,
432	          });
433	          continue;
434	        }
435	
436	        // ── Generate briefing ────────────────────────────────────────────────
437	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
438	        const baseContext = generateBriefing({
439	          taskId: task.id,
440	          featureId,
441	          taskTitle: task.title,
442	          taskBranch,
443	          taskRepo: task.repo,
444	          taskRepoRoot,
445	          workspaceRoot: workspaceLocalPath,
446	          gitAuthorEmail,
447	          gitAuthorName,
448	          implementationModel,
449	          resultPath,
450	        });
451	        const briefingContent = ragPreFlight.block
452	          ? `${baseContext}\n\n${ragPreFlight.block}`
453	          : baseContext;
454	
455	        // ── Write briefing via BriefingTransportPort ─────────────────────────
456	        // Use taskId as the briefing handle so the file path matches the
457	        // existing briefing-{taskId}/briefing.md convention.
458	        const briefingPath = await ports.briefing.put(task.id, briefingContent);
459	
460	        // ── Build ExecutorPortInput ──────────────────────────────────────────
461	        const nonce = randomUUID();
462	        const callbackUrl = ports.broker.getCallbackUrl() ?? "";
463	
464	        const execInput: ExecutorPortInput = {
465	          taskId: task.id,
466	          featureId,
467	          workspaceId: workspaceYaml.workspace_id,
468	          taskRepoUrl,
469	          taskRepoBranch: taskBranch,
470	          taskRepoPath: taskRepoRoot,
471	          briefingPath,
472	          resultPath,
473	          budgetTokens: config.budget.max_tokens_per_task,
474	          implementationModel,
475	          sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
476	          githubToken,
477	          callbackUrl,
478	          nonce,
479	        };
480	
481	        // ── Submit executor (async — T6) ─────────────────────────────────────
482	        // A fresh adapter is created per task to carry task-scoped extraEnv;
483	        // the profile's broker and other ports are reused.
484	        const taskExtraEnv: Record<string, string> = {
485	          WORKSPACE_ROOT: workspaceLocalPath,
486	          TASK_BRANCH: taskBranch,
487	          GIT_AUTHOR_EMAIL: gitAuthorEmail,
488	          GIT_AUTHOR_NAME: gitAuthorName,
489	          WORKFLOW_LOCAL_PATH: workflowLocalPath,
490	          MAX_TURNS: String(config.budget.max_iterations),
491	          LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
492	          ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
493	          ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
494	            ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
495	            : {}),
496	        };
497	        const perTaskExecutor =
498	          runtimeProfile === "local-docker"
499	            ? new (await import("./adapters/executor/docker-run.js")).DockerRunAdapter({
500	                broker: ports.broker,
501	                extraEnv: taskExtraEnv,
502	              })
503	            : new SubProcessAdapter({
504	                broker: ports.broker,
505	                extraEnv: taskExtraEnv,
506	              });
507	
508	        const execHandle = await perTaskExecutor.submit(execInput);
509	
510	        // Persist handle to task YAML for broker crash-recovery reconciliation.
511	        try {
512	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
513	        } catch (e) {
514	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
515	        }
516	
517	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
518	        if (runtimeProfile === "local-docker") dockerInFlight++;
519	        outcome = "ran_task";
520	        break outerLoop;
521	      }
522	    }
523	    } // end dispatchBlock
524	
525	    // ── In-review PR poll ─────────────────────────────────────────────────────
526	    // In local-subprocess mode the executor subprocess shares the same container
527	    // filesystem as the orchestrator. Both can race on `git rebase` in the same
528	    // repo — a second rebase operation fails with "rebase-merge directory already
529	    // exists". Re-check in-flight count here (not just in dispatchBlock) because
530	    // pulledWorkspaceRoots is already populated on the same cycle that dispatched
531	    // the executor; the dispatchBlock early-break only fires on *subsequent* cycles.
532	    const skipPrPoll =
533	      runtimeProfile === "local-subprocess" &&
534	      (ports.broker as InMemoryBrokerAdapter).registrySize() > 0;
535	    if (githubToken && !skipPrPoll) {
536	      const prPollIntervalMs =
537	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
538	      const now = Date.now();
539	
540	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
541	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
542	        try {
543	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
544	            workspaceRoots: pulledWorkspaceRoots,
545	            githubToken,
546	            emit,
547	          });
548	
549	          for (const wsRoot of pulledWorkspaceRoots) {
550	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
551	            if (wsResults.some((r) => r.mergeable === false)) {
552	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
553	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
554	              await handleMergeConflicts({
555	                prResults: wsResults,
556	                workspaceRoot: wsRoot,
557	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
558	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
559	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
560	                gitAuthorEmail,
561	                gitAuthorName,
562	                sshKeyPath,
563	                emit,
564	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
565	              });
566	            }
567	          }
568	
569	          for (const wsRoot of pulledWorkspaceRoots) {
570	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
571	            if (wsResults.some((r) => r.hasOpenComments === true)) {
572	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
573	              await handleDraftReviews({
574	                prResults: wsResults,
575	                workspaceRoot: wsRoot,
576	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
577	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
578	                resolveImplementationModel: (fId, tId) => {
579	                  try {
580	                    const tMdPath = join(wsRoot, "docs", "features", fId, "tasks.md");
581	                    const overrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), tId);
582	                    return resolveModel(wsModelPolicy, overrides, "implementation", tId);
583	                  } catch {
584	                    return resolveModel(wsModelPolicy, {}, "implementation", tId);
585	                  }
586	                },
587	                gitAuthorEmail,
588	                gitAuthorName,
589	                sshKeyPath,
590	                workflowLocalPath,
591	                maxTurns: config.budget.max_iterations,
592	                maxTokens: config.budget.max_tokens_per_task,
593	                logSinkEnabled: config.log_sink.enabled,
594	                workspaceId: (() => {
595	                  try {
596	                    return (parseYaml(readFileSync(workspaceYamlPath(wsRoot), "utf-8")) as { workspace_id: string }).workspace_id ?? "";
597	                  } catch { return ""; }
598	                })(),
599	                githubToken,
600	                resolveImplRepoUrl: (repoId) => resolveRepoGitUrl(wsRoot, repoId),
601	                broker: ports.broker,
602	                callbackUrl: ports.broker.getCallbackUrl() ?? "",
603	                emit,
604	              });
605	            }
606	          }
607	
608	          for (const wsRoot of pulledWorkspaceRoots) {
609	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
610	            if (wsResults.some((r) => r.merged === true)) {
611	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
612	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
613	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
614	              await handleMergedPrs({
615	                prResults: wsResults,
616	                workspaceRoot: wsRoot,
617	                mgmtRepoOwner: mgmtCoords.owner,
618	                mgmtRepoName: mgmtCoords.repo,
619	                mgmtBaseBranch: mgmtCoords.baseBranch,
620	                githubToken,
621	                gitAuthorEmail,
622	                gitAuthorName,
623	                sshKeyPath,
624	                emit,
625	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
626	              });
627	            }
628	          }
629	
630	          for (const wsRoot of pulledWorkspaceRoots) {
631	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
632	            if (wsRecoveries.length > 0) {
633	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
634	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
635	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
636	              await handleWorkspacePrRecoveries({
637	                recoveries: wsRecoveries,
638	                mgmtRepoOwner: mgmtCoords.owner,
639	                mgmtRepoName: mgmtCoords.repo,
640	                mgmtBaseBranch: mgmtCoords.baseBranch,
641	                githubToken,
642	                gitAuthorEmail,
643	                gitAuthorName,
644	                sshKeyPath,
645	                emit,
646	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
647	              });
648	            }
649	          }
650	        } catch (e) {
651	          emit({ type: "in_review_poll_error", details: String(e) });
652	        }
653	      }
654	    }
655	
656	    // ── Shared reap loop ──────────────────────────────────────────────────────
657	    // Drain completions posted by in-flight executors this cycle (and any
658	    // leftovers from previous cycles). Routes by handle.kind → dispatcher.
659	    try {
660	      const reapResult = await runReapLoop({
661	        broker: ports.broker,
662	        workspaceRoots: pulledWorkspaceRoots,
663	        gitAuthorEmail,
664	        gitAuthorName,
665	        sshKeyPath,
666	        githubToken,
667	        emit,
668	      });
669	      if (reapResult.dispatched > 0) {
670	        if (runtimeProfile === "local-docker") {
671	          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
672	        }
673	        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
674	        if (outcome === "idle") outcome = "ran_task";
675	      }
676	    } catch (e) {
677	      emit({ type: "reap_loop_error", details: String(e) });
678	    }
679	
680	    return outcome;
681	  }
682	
683	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
684	  return 0;
685	}
686	
687	main()
688	  .then((code) => process.exit(code))
689	  .catch((e) => {
690	    try {
691	      console.log(JSON.stringify({
692	        type: "fatal_error",
693	        details: (e as Error).message ?? String(e),
694	        at: new Date().toISOString(),
695	      }));
696	    } catch { /* last resort */ }
697	    process.exit(4);
698	  });
