1	/**
2	 * Per-cycle in_review PR status poller.
3	 *
4	 * For every `in_review` task across all watched workspaces, calls the GitHub
5	 * GraphQL API to fetch: mergeable state, draft state, and unresolved inline
6	 * review threads.
7	 *
8	 * General PR-level issue comments are intentionally ignored — they are not
9	 * trackable without identity-dependent heuristics and cause dispatch loops.
10	 * Only inline review threads (which have a first-class `isResolved` bit on
11	 * GitHub's side) are used to determine whether a review agent should run.
12	 *
13	 * Pure read — no task YAML mutations.
14	 *
15	 * On API errors, emits `in_review_poll_error` and skips that task.
16	 * Results are passed to the T3 (auto-rebase) and T4 (open-comment) handlers.
17	 */
18	
19	import { existsSync, readFileSync, readdirSync } from "node:fs";
20	import { join } from "node:path";
21	import { spawnSync } from "node:child_process";
22	import { parse as parseYaml } from "yaml";
23	import type { Task } from "../types/task.js";
24	import { featuresRoot, TASKS_DIR, taskBranchName, taskYamlRelPath } from "../paths.js";
25	import { TERMINAL_STATUSES, tryReadTaskFromBranch } from "../task-branch-state.js";
26	
27	// ── Public types ──────────────────────────────────────────────────────────────
28	
29	/**
30	 * A done task found on a feature branch whose workspace PR has not been merged.
31	 * Returned by checkInReviewPrs so the main loop can retry the merge.
32	 */
33	export interface WorkspacePrRecovery {
34	  taskId: string;
35	  featureId: string;
36	  workspaceRoot: string;
37	  /** URL of the management-repo PR that needs to be merged. */
38	  workspacePrUrl: string;
39	}
40	
41	/** Combined result from a single checkInReviewPrs call. */
42	export interface CheckInReviewResult {
43	  /** One entry per successfully-polled in_review task. */
44	  prResults: PrStatusResult[];
45	  /** Done tasks on feature branches whose workspace PR is still open. */
46	  workspacePrRecoveries: WorkspacePrRecovery[];
47	}
48	
49	/** Status reported by the GitHub GraphQL API for a single in_review task's PR. */
50	export interface PrStatusResult {
51	  taskId: string;
52	  featureId: string;
53	  /** Absolute path to the management workspace that owns this task. */
54	  workspaceRoot: string;
55	  /**
56	   * Whether the PR can be cleanly merged into the base branch.
57	   * null means GitHub has not finished computing the mergeability yet.
58	   */
59	  mergeable: boolean | null;
60	  /** True when the PR is in draft state. */
61	  draft: boolean;
62	  /**
63	   * True when the PR has at least one unresolved inline review thread.
64	   * General PR-level issue comments are not tracked.
65	   * This is the trigger for dispatching the respond-to-review agent.
66	   */
67	  hasOpenComments: boolean;
68	  /** True when the PR has been merged into the base branch. */
69	  merged: boolean;
70	  /**
71	   * True when the task's feature branch no longer exists on origin.
72	   * This happens when the workspace PR was squash-merged and the branch
73	   * was auto-deleted before the orchestrator could run handleMergedPrs.
74	   * handleMergedPrs will recreate the branch from mgmtBaseBranch in this case.
75	   */
76	  branchMissing?: boolean;
77	}
78	
79	export interface CheckInReviewPrsOptions {
80	  /** Absolute paths to management workspace repos to scan. */
81	  workspaceRoots: string[];
82	  /** GitHub personal access token for API authentication. */
83	  githubToken: string;
84	  emit: (event: Record<string, unknown>) => void;
85	}
86	
87	// ── Internal helpers ──────────────────────────────────────────────────────────
88	
89	/**
90	 * Parse owner, repo, and pull number from a GitHub PR URL.
91	 * Accepts https://github.com/{owner}/{repo}/pull/{number}
92	 * Returns null for any non-matching URL.
93	 */
94	export function parsePrUrl(
95	  url: string,
96	): { owner: string; repo: string; pullNumber: number } | null {
97	  const match = /https?:\/\/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(url);
98	  if (!match) return null;
99	  return {
100	    owner: match[1],
101	    repo: match[2],
102	    pullNumber: parseInt(match[3], 10),
103	  };
104	}
105	
106	interface GitHubGraphQLPrData {
107	  isDraft: boolean;
108	  merged: boolean;
109	  mergeable: "MERGEABLE" | "CONFLICTING" | "UNKNOWN";
110	  reviewThreads: { nodes: Array<{ isResolved: boolean }> };
111	}
112	
113	interface GitHubGraphQLResponse {
114	  data?: { repository?: { pullRequest?: GitHubGraphQLPrData | null } | null };
115	  errors?: Array<{ message: string }>;
116	}
117	
118	const PR_STATUS_QUERY = `
119	query($owner: String!, $name: String!, $number: Int!) {
120	  repository(owner: $owner, name: $name) {
121	    pullRequest(number: $number) {
122	      isDraft
123	      merged
124	      mergeable
125	      reviewThreads(first: 100) { nodes { isResolved } }
126	    }
127	  }
128	}`.trim();
129	
130	/**
131	 * Call the GitHub GraphQL API via curl to get PR status and unresolved review threads.
132	 * Throws on curl failure, empty response, or GraphQL errors.
133	 */
134	function fetchPrStatus(
135	  owner: string,
136	  repo: string,
137	  pullNumber: number,
138	  githubToken: string,
139	): { draft: boolean; merged: boolean; mergeable: boolean | null; hasOpenComments: boolean } {
140	  const body = JSON.stringify({
141	    query: PR_STATUS_QUERY,
142	    variables: { owner, name: repo, number: pullNumber },
143	  });
144	
145	  const result = spawnSync(
146	    "curl",
147	    [
148	      "-s", "-X", "POST",
149	      "-H", `Authorization: Bearer ${githubToken}`,
150	      "-H", "Content-Type: application/json",
151	      "-H", "Accept: application/vnd.github+json",
152	      "-d", body,
153	      "https://api.github.com/graphql",
154	    ],
155	    { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
156	  );
157	
158	  if (result.error) throw result.error;
159	  const stdout = result.stdout ?? "";
160	  if (!stdout.trim()) throw new Error(`curl returned empty response. stderr: ${result.stderr ?? ""}`);
161	
162	  const gql = JSON.parse(stdout) as GitHubGraphQLResponse;
163	  if (gql.errors?.length) {
164	    throw new Error(`GraphQL errors: ${gql.errors.map((e) => e.message).join("; ")}`);
165	  }
166	
167	  const pr = gql.data?.repository?.pullRequest;
168	  if (!pr) throw new Error("GraphQL response missing pullRequest data");
169	
170	  const mergeableRaw = pr.mergeable;
171	  const mergeable =
172	    mergeableRaw === "MERGEABLE" ? true :
173	    mergeableRaw === "CONFLICTING" ? false : null;
174	
175	  const hasOpenComments = pr.reviewThreads.nodes.some((t) => !t.isResolved);
176	
177	  return {
178	    draft: pr.isDraft,
179	    merged: pr.merged,
180	    mergeable,
181	    hasOpenComments,
182	  };
183	}
184	
185	
186	// ── Public API ────────────────────────────────────────────────────────────────
187	
188	/**
189	 * Scan all watched workspaces for `in_review` tasks whose PR URL is set,
190	 * then call the GitHub API for each to get current mergeability and draft state.
191	 *
192	 * Also detects `done` tasks that are on a feature branch but whose workspace PR
193	 * has not yet been merged, returning them as `workspacePrRecoveries` so the
194	 * main loop can retry the merge.
195	 *
196	 * Pure read — no task YAML mutations.
197	 */
198	export async function checkInReviewPrs(
199	  opts: CheckInReviewPrsOptions,
200	): Promise<CheckInReviewResult> {
201	  const { workspaceRoots, githubToken, emit } = opts;
202	  const prResults: PrStatusResult[] = [];
203	  const workspacePrRecoveries: WorkspacePrRecovery[] = [];
204	
205	  emit({ type: "in_review_poll_start", workspace_count: workspaceRoots.length });
206	
207	  for (const workspaceRoot of workspaceRoots) {
208	    const docsPath = featuresRoot(workspaceRoot);
209	    if (!existsSync(docsPath)) continue;
210	
211	    let featureDirs: string[];
212	    try {
213	      featureDirs = readdirSync(docsPath, { withFileTypes: true })
214	        .filter((e) => e.isDirectory())
215	        .map((e) => e.name);
216	    } catch {
217	      continue;
218	    }
219	
220	    for (const featureId of featureDirs) {
221	      const tasksDir = join(docsPath, featureId, TASKS_DIR);
222	      if (!existsSync(tasksDir)) continue;
223	
224	      let taskFiles: string[];
225	      try {
226	        taskFiles = readdirSync(tasksDir).filter((f) =>
227	          /^T\d+\.yaml$/.test(f),
228	        );
229	      } catch {
230	        continue;
231	      }
232	
233	      for (const fileName of taskFiles) {
234	        let task: Task;
235	        try {
236	          task = parseYaml(
237	            readFileSync(join(tasksDir, fileName), "utf-8"),
238	          ) as Task;
239	        } catch {
240	          continue;
241	        }
242	
243	        // If the task is in-flight on main, the live state is on the feature branch.
244	        // If the branch doesn't exist yet, there's nothing to poll — skip.
245	        let readFromBranch = false;
246	        let branchMissing = false;
247	        if (!TERMINAL_STATUSES.has(task.status)) {
248	          const taskId = fileName.replace(/\.yaml$/, "");
249	          const branch = taskBranchName(featureId, taskId);
250	          const relPath = taskYamlRelPath(featureId, taskId);
251	          const branchTask = tryReadTaskFromBranch(workspaceRoot, branch, relPath);
252	          if (!branchTask) {
253	            // Branch missing. If the task is in_review with a pr.url set, the branch was
254	            // likely deleted after a manual workspace-PR squash-merge while an executor was
255	            // in-flight (skipPrPoll guard). Fall back to the main YAML so the implementation
256	            // PR can still be polled and handleMergedPrs can recreate the branch.
257	            if (task.status === "in_review" && task.pr?.url) {
258	              branchMissing = true;
259	              emit({
260	                type: "in_review_poll_branch_missing_fallback",
261	                task_id: taskId,
262	                feature_id: featureId,
263	                note: "feature branch gone — falling back to main YAML for impl PR poll",
264	              });
265	              // task stays as the main YAML; readFromBranch stays false.
266	            } else {
267	              emit({
268	                type: "in_review_poll_skip",
269	                task_id: taskId,
270	                feature_id: featureId,
271	                reason: "branch_not_found",
272	              });
273	              continue;
274	            }
275	          } else {
276	            task = branchTask;
277	            readFromBranch = true;
278	          }
279	        }
280	
281	        // Recovery: task is done on the feature branch but the workspace (management-repo)
282	        // PR hasn't been merged yet. Queue for retry rather than polling the impl PR.
283	        // Skip if workspace_pr.status is already "merged" — nothing left to do.
284	        if (readFromBranch && task.status === "done" && task.workspace_pr?.url &&
285	            task.workspace_pr.status !== "merged") {
286	          emit({
287	            type: "workspace_pr_recovery_candidate",
288	            task_id: task.id,
289	            feature_id: featureId,
290	            workspace_pr_url: task.workspace_pr.url,
291	          });
292	          workspacePrRecoveries.push({
293	            taskId: task.id,
294	            featureId,
295	            workspaceRoot,
296	            workspacePrUrl: task.workspace_pr.url,
297	          });
298	          continue;
299	        }
300	
301	        // Only poll in_review tasks with a PR URL set.
302	        if (task.status !== "in_review") continue;
303	        if (!task.pr?.url) {
304	          emit({
305	            type: "in_review_poll_skip",
306	            task_id: task.id,
307	            feature_id: featureId,
308	            reason: "no_pr_url",
309	          });
310	          continue;
311	        }
312	
313	        const coords = parsePrUrl(task.pr.url);
314	        if (!coords) {
315	          emit({
316	            type: "in_review_poll_error",
317	            task_id: task.id,
318	            feature_id: featureId,
319	            details: `Cannot parse PR URL: ${task.pr.url}`,
320	          });
321	          continue;
322	        }
323	
324	        emit({
325	          type: "in_review_poll_fetching",
326	          task_id: task.id,
327	          feature_id: featureId,
328	          pr_url: task.pr.url,
329	        });
330	
331	        try {
332	          const prStatus = fetchPrStatus(
333	            coords.owner,
334	            coords.repo,
335	            coords.pullNumber,
336	            githubToken,
337	          );
338	
339	          emit({
340	            type: "in_review_poll_result",
341	            task_id: task.id,
342	            feature_id: featureId,
343	            pr_url: task.pr.url,
344	            merged: prStatus.merged,
345	            draft: prStatus.draft,
346	            mergeable: prStatus.mergeable,
347	            has_open_comments: prStatus.hasOpenComments,
348	          });
349	
350	          prResults.push({
351	            taskId: task.id,
352	            featureId,
353	            workspaceRoot,
354	            mergeable: prStatus.mergeable,
355	            draft: prStatus.draft,
356	            merged: prStatus.merged,
357	            hasOpenComments: prStatus.hasOpenComments,
358	            ...(branchMissing ? { branchMissing: true } : {}),
359	          });
360	        } catch (e) {
361	          emit({
362	            type: "in_review_poll_error",
363	            task_id: task.id,
364	            feature_id: featureId,
365	            details: String(e),
366	          });
367	        }
368	      }
369	    }
370	  }
371	
372	  emit({
373	    type: "in_review_poll_done",
374	    polled: prResults.length,
375	    merged: prResults.filter((r) => r.merged).length,
376	    has_open_comments: prResults.filter((r) => r.hasOpenComments).length,
377	    conflicting: prResults.filter((r) => r.mergeable === false).length,
378	    workspace_pr_recoveries: workspacePrRecoveries.length,
379	  });
380	
381	  return { prResults, workspacePrRecoveries };
382	}
