2	 * Orchestrator side-effect: append a log entry to a task YAML file.
3	 *
4	 * Handles the git add/commit/push of the updated YAML to the task's feature
5	 * branch. All callers delegate log-entry appending here rather than writing
6	 * directly to avoid duplicating the git plumbing.
7	 */
8	
9	import { readFileSync, writeFileSync } from "node:fs";
10	import { execSync, spawnSync } from "node:child_process";
11	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
12	import type { Task, TaskLogEntry } from "../types/task.js";
13	import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
14	import { buildGitEnv } from "../git-env.js";
15	
16	export interface AppendLogOpts {
17	  workspaceRoot: string;
18	  featureId: string;
19	  taskId: string;
20	  taskBranch: string;
21	  entry: Omit<TaskLogEntry, "at"> & { at?: string };
22	  gitAuthorEmail: string;
23	  gitAuthorName?: string;
24	  sshKeyPath?: string;
25	  commitMessage?: string;
26	}
27	
28	/**
29	 * Append a log entry to the task YAML on disk and commit+push to the task branch.
30	 *
31	 * Non-throwing: errors are returned as strings rather than thrown so the caller
32	 * can decide how to handle a partial log failure without halting the cycle.
33	 *
34	 * Returns undefined on success, or an error string on failure.
35	 */
36	export function appendLogEntry(opts: AppendLogOpts): string | undefined {
37	  const {
38	    workspaceRoot,
39	    featureId,
40	    taskId,
41	    taskBranch,
42	    entry,
43	    gitAuthorEmail,
44	    gitAuthorName = gitAuthorEmail,
45	    sshKeyPath,
46	    commitMessage,
47	  } = opts;
48	
49	  const at = entry.at ?? new Date().toISOString();
50	  const fullEntry: TaskLogEntry = { ...entry, at } as TaskLogEntry;
51	
52	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
53	  const relPath = taskYamlRelPath(featureId, taskId);
54	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
55	  const msg = commitMessage ?? `chore(${taskId}): append ${fullEntry.action} log entry`;
56	
57	  // Step 1: Re-anchor to the task branch tip BEFORE reading or writing any files.
58	  // checkout -B resets the working tree to origin state, so any prior local
59	  // writes must happen after this step — not before.
60	  try {
61	    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
62	    execSync(`git -C "${workspaceRoot}" checkout -- .`, { env, stdio: "pipe" });
63	    execSync(
64	      `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
65	      { env, stdio: "pipe" },
66	    );
67	  } catch (e) {
68	    return `git fetch/checkout task branch failed: ${String(e)}`;
69	  }
70	
71	  // Step 2: Read YAML from the now-correct branch state.
72	  let task: Task;
73	  try {
74	    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
75	  } catch (e) {
76	    return `failed to read task YAML: ${String(e)}`;
77	  }
78	
79	  task.log.push(fullEntry);
80	  task.execution.last_updated_by = gitAuthorEmail;
81	  task.execution.last_updated_at = at;
82	
83	  // Step 3: Write the mutated YAML (after checkout so the write is not overwritten).
84	  try {
85	    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
86	  } catch (e) {
87	    return `failed to write task YAML: ${String(e)}`;
88	  }
89	
90	  try {
91	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
92	    execSync(`git -C "${workspaceRoot}" commit -m "${msg}"`, { env, stdio: "pipe" });
93	  } catch (e) {
94	    return `git add/commit failed: ${String(e)}`;
95	  }
96	
97	  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
98	    env,
99	    encoding: "utf-8",
100	  });
101	  if (push.status !== 0) {
102	    return `git push failed: ${push.stderr}`;
103	  }
104	
105	  return undefined;
106	}
