    // Fall through to normal blocked handling if we can't read the task.
  }

  if (task !== null) {
    const retriedCount = task.log.filter((e) => e.action === "retried").length;

    if (retriedCount < maxRetries) {
      // Retry: reset to ready, append retried log entry.
      const retryEntry: Omit<TaskLogEntry, "at"> = {
        action: "retried",
        by: gitAuthorEmail,
        note: `Retry ${retriedCount + 1}/${maxRetries} — original reason: ${result.blocked_reason}`,
        ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
        ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
      };

