      // We need to directly set status=ready here — use the append-log path
      // after patching the YAML via a mutate with in_review (then override below).
      // Simpler: inline the git mutation for the retry path.
      const retryResult: ExecutorResult = {
        terminal_status: "blocked",
        blocked_reason: "retry_reset_ready",
      };
      // Write status=ready via mutateTaskYaml in a two-step: first use the
      // existing mutate helper but override the resulting status immediately.
      // Since mutateTaskYaml doesn't support "ready", we inline it here.
      const retryErr = appendLogEntry({
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        entry: retryEntry,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        commitMessage: `chore(${taskId}): retried (${retriedCount + 1}/${maxRetries}) — reset to ready`,
      });
      if (retryErr) {
        emit({ type: "retry_log_failed", task_id: taskId, details: retryErr });
        // Fall through to normal blocked handling.
