          featureId,
          taskId,
          taskBranch,
          newStatus: "ready",
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
        });
        if (mutateErr) {
          emit({ type: "retry_reset_failed", task_id: taskId, details: mutateErr });
          // Fall through to normal blocked handling.
