    workspaceRoot,
    taskId,
    featureId,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    jitterMaxSeconds = 0.5,
    skipJitter = false,
    skipGit = false,
