  const now = new Date().toISOString();
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  task.log.push({
    action: "reviewer_started",
    by: gitAuthorEmail,
    at: now,
    note: "Reviewer agent claimed via git-based claim protocol.",
  });
