/**
 * Find all `change_requested` tasks in the workspace that are eligible for
 * fix-agent dispatch.
 *
 * Eligibility criteria:
 *   1. task.status === "change_requested" on the feature branch (live state)
 *   2. task.pr?.url is set (the impl PR exists — fix agent needs it)
 *   3. task.repo is in the watched workspace
 *   4. The workspace management repo is in agent.watches
 *
 * Returns tasks sorted ascending by numeric task ID.
 */
export function findFixableTasks(
  agentConfig: AgentConfig,
  workspaceRoot: string,
): EligibleTask[] {
  const workspaceConfig = loadWorkspaceConfig(workspaceRoot);
  const managementRepo = workspaceConfig.repos.find(
    (r) => r.id === workspaceConfig.management_repo,
  );
  if (!managementRepo) return [];
  if (!new Set(agentConfig.watches).has(managementRepo.github)) return [];

  const reachableRepoIds = new Set(workspaceConfig.repos.map((r) => r.id));
  const allEntries = scanAllFeatures(workspaceRoot);

  const fixable: EligibleTask[] = [];

  for (const { task, featureId } of allEntries) {
    if (!reachableRepoIds.has(task.repo)) continue;

    // Read live status from task branch
    const branch = taskBranchName(featureId, task.id);
    const relPath = taskYamlRelPath(featureId, task.id);
    const liveTask = tryReadTaskFromBranch(workspaceRoot, branch, relPath) ?? task;

    if (liveTask.status !== "change_requested") continue;
    if (!liveTask.pr?.url) continue;

    fixable.push({ task: liveTask, featureId });
  }

  fixable.sort((a, b) => taskNumericId(a.task.id) - taskNumericId(b.task.id));
  return fixable;
}

/**
 * Find all `in_review` tasks in the workspace that are eligible for
 * reviewer-agent dispatch.
 *
 * Eligibility criteria:
 *   1. task.status === "in_review" on the feature branch (live state)
 *   2. task.pr?.url is set (the impl PR exists — reviewer needs it)
 *   3. The last log entry is NOT already `reviewer_started` (anti-duplicate guard)
 *   4. task.repo is in the watched workspace
 *   5. The workspace management repo is in agent.watches
 *
 * Returns tasks sorted ascending by numeric task ID.
 */
export function findReviewableTasks(
  agentConfig: AgentConfig,
  workspaceRoot: string,
): EligibleTask[] {
  const workspaceConfig = loadWorkspaceConfig(workspaceRoot);
  const managementRepo = workspaceConfig.repos.find(
    (r) => r.id === workspaceConfig.management_repo,
  );
  if (!managementRepo) return [];
  if (!new Set(agentConfig.watches).has(managementRepo.github)) return [];

  const reachableRepoIds = new Set(workspaceConfig.repos.map((r) => r.id));
  const allEntries = scanAllFeatures(workspaceRoot);

  const reviewable: EligibleTask[] = [];

  for (const { task, featureId } of allEntries) {
    if (!reachableRepoIds.has(task.repo)) continue;

    // Read live status from task branch
    const branch = taskBranchName(featureId, task.id);
    const relPath = taskYamlRelPath(featureId, task.id);
    const liveTask = tryReadTaskFromBranch(workspaceRoot, branch, relPath) ?? task;

    if (liveTask.status !== "in_review") continue;
    if (!liveTask.pr?.url) continue;

    // Anti-duplicate: skip if already claimed by a reviewer
    const lastEntry = liveTask.log?.[liveTask.log.length - 1];
    if (lastEntry?.action === "reviewer_started") continue;

    reviewable.push({ task: liveTask, featureId });
  }

  reviewable.sort((a, b) => taskNumericId(a.task.id) - taskNumericId(b.task.id));
  return reviewable;
}
