/**
 * Review result dispatcher — skeleton.
 *
 * Routes the reviewer agent's result to the appropriate side-effect handler:
 *   passed          → Auto-Done Writer (T5): write done + auto-ready cascade
 *   change_requested → Mutate task to change_requested (T4)
 *   escalate        → Escalation Handler (T6): Slack + blocked
 *
 * T5 and T6 fill in the handler bodies. T4 fills change_requested handling.
 * T2 provides only the routing skeleton and the stub event emissions.
 */

import { taskBranchName } from "../paths.js";
import { appendLogEntry } from "./append-log.js";
import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";

// ── Public types ──────────────────────────────────────────────────────────────

/** The result written by the reviewer executor to result.json. */
export interface ReviewResult {
  terminal_status: "passed" | "change_requested" | "escalate";
  /** Human-readable verdict summary. */
  verdict?: string;
  /** Confidence level: high | medium | low */
  confidence?: string;
  /** Reviewer notes — passed through to downstream handlers. */
  notes?: string;
  /** URL of the GitHub review posted by the reviewer. */
  review_url?: string;
}

export interface DispatchReviewResultOpts {
  result: ReviewResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Route a reviewer result to the correct side-effect handler.
 *
 * Non-throwing: all errors are emitted and swallowed so the reap loop
 * can ack the completion and move on.
 */
export async function dispatchReviewResult(opts: DispatchReviewResultOpts): Promise<void> {
  const {
    result,
    workspaceRoot,
    featureId,
    taskId,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    emit,
  } = opts;

  const taskBranch = taskBranchName(featureId, taskId);

  try {
    switch (result.terminal_status) {
      case "passed": {
        // TODO T5: Auto-Done Writer — write done log entry + auto-ready cascade.
        // Skeleton: emit event so downstream tests can assert routing.
        emit({
          type: "review_passed",
          task_id: taskId,
          feature_id: featureId,
          verdict: result.verdict,
          notes: result.notes,
          note: "auto-done writer stub — T5 fills this",
        });
        break;
      }

      case "change_requested": {
        // Mutate task to change_requested, record review URL in log.
        const err = mutateTaskYamlDirect({
          workspaceRoot,
          featureId,
          taskId,
          taskBranch,
          newStatus: "change_requested",
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
        });
        if (err) {
          emit({ type: "review_change_requested_mutate_failed", task_id: taskId, feature_id: featureId, details: err });
          return;
        }

        const logErr = appendLogEntry({
          workspaceRoot,
          featureId,
