open('runtime/orchestrator/src/side-effects/dispatch.ts', 'w').write('''/**
 * Orchestrator side-effect dispatcher.
 *
 * Translates an ExecutorResult into the correct set of side effects.
 * Max-turns retry: blocked + blocked_reason.startsWith("max_turns") → reset to "ready"
 * up to EXECUTOR_MAX_RETRIES times before permanently blocking.
 */

import { readFileSync } from "node:fs";
import { parse as parseYaml } from "yaml";
import type { ExecutorResult } from "@workflow/runtime-abi";
import type { Task, TaskLogEntry } from "../types/task.js";
import { taskYamlAbsPath } from "../paths.js";
import { mutateTaskYaml } from "./mutate-task-yaml.js";
import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";
import { appendLogEntry } from "./append-log.js";

export interface DispatchExecutorResultOpts {
  result: ExecutorResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  taskTitle: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

export async function dispatchExecutorResult(opts: DispatchExecutorResultOpts): Promise<void> {
  const { result, workspaceRoot, featureId, taskId, taskBranch, gitAuthorEmail, gitAuthorName, sshKeyPath, emit } = opts;

  const EXECUTOR_MAX_RETRIES = Number(process.env.EXECUTOR_MAX_RETRIES ?? "3");

  if (
    result.terminal_status === "blocked" &&
    typeof result.blocked_reason === "string" &&
    result.blocked_reason.startsWith("max_turns")
  ) {
    let task: Task | undefined;
    try {
      task = parseYaml(readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8")) as Task;
    } catch { /* fall through to blocked handling */ }

    if (task !== undefined) {
      const retriedCount = (task.log ?? []).filter((e) => e.action === "retried").length;

      if (retriedCount < EXECUTOR_MAX_RETRIES) {
        const logErr = appendLogEntry({
          workspaceRoot, featureId, taskId, taskBranch,
          entry: {
            action: "retried", by: gitAuthorEmail,
            note: `max_turns retry ${retriedCount + 1}/${EXECUTOR_MAX_RETRIES}`,
            ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
            ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
          },
          gitAuthorEmail, gitAuthorName, sshKeyPath,
        });
        if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });

        const mutateErr = mutateTaskYamlDirect({ workspaceRoot, featureId, taskId, taskBranch, newStatus: "ready", gitAuthorEmail, gitAuthorName, sshKeyPath });
        if (!mutateErr) {
          emit({ type: "task_retried", task_id: taskId, feature_id: featureId, attempt: retriedCount + 1, max: EXECUTOR_MAX_RETRIES });
          return;
        }
        emit({ type: "retry_reset_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
      } else {
        emit({ type: "task_max_retries_exceeded", task_id: taskId, feature_id: featureId, retried_count: retriedCount });
      }
    }
  }

  const prUrl = result.pr_url;

  if (result.terminal_status === "in_review") {
    if (prUrl) emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    const mutateErr = mutateTaskYaml({ workspaceRoot, featureId, taskId, taskBranch, result, prUrl, gitAuthorEmail, gitAuthorName, sshKeyPath });
    if (mutateErr) {
      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
      throw new Error(mutateErr);
    }
    const entry: Omit<TaskLogEntry, "at"> = {
      action: "run_completed", by: gitAuthorEmail,
      note: prUrl ? `Implementation PR: ${prUrl}` : "Implementation complete.",
      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
    };
    const logErr = appendLogEntry({ workspaceRoot, featureId, taskId, taskBranch, entry, gitAuthorEmail, gitAuthorName, sshKeyPath });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  } else {
    if (prUrl) emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    const mutateErr = mutateTaskYaml({ workspaceRoot, featureId, taskId, taskBranch, result, prUrl, gitAuthorEmail, gitAuthorName, sshKeyPath });
    if (mutateErr) {
      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
      throw new Error(mutateErr);
    }
    const entry: Omit<TaskLogEntry, "at"> = {
      action: "blocked", by: gitAuthorEmail,
      note: result.blocked_reason ?? "executor returned non-in_review status",
      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
    };
    const logErr = appendLogEntry({ workspaceRoot, featureId, taskId, taskBranch, entry, gitAuthorEmail, gitAuthorName, sshKeyPath });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  }
}
''')

