    execution: { actor_type: "agent", last_updated_by: null, last_updated_at: null },
    pr: { url: "", status: "not_created" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

function makeWorkspace(task: Task, extraYaml: Record<string, unknown> = {}): string {
  const dir = mkdtempSync(join(tmpdir(), "dispatch-ctrl-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task));
  const ws = { management_repo: "workspace", repos: [{ id: "impl-repo", github: MGMT_URL }, { id: "workspace", github: MGMT_URL }], ...extraYaml };
  writeFileSync(join(dir, "workspace.yaml"), yamlStringify(ws));
  return dir;
}

function makeAgentConfig(): AgentConfig {
  return {
    watches: [MGMT_URL],
    budget: { max_tokens_per_task: 100000, max_iterations: 10 },
    idle_sleep_seconds: 0,
    jitter_max_seconds: 0,
    max_concurrent_executors: 1,
    pr_poll_interval_seconds: 60,
    log_sink: { enabled: false },
  } as unknown as AgentConfig;
}

