describe("dispatchExecutorResult — max-turns retry", () => {
  it("emits task_retried and returns early when below retry limit", async () => {
    const task = makeTask({ status: "in_progress", log: [] });
    const wsRoot = makeWorkspace(task);
    mockExecSync();
    mockSpawnSync(0);

    const events: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result: { terminal_status: "blocked", blocked_reason: "max_turns_exceeded" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: "test",
      taskRepoUrl: "git@github.com:org/impl.git",
      taskBaseBranch: "main",
      githubToken: "ghp_test",
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e["type"] === "task_retried")).toBe(true);
    expect(events.some((e) => e["type"] === "blocked")).toBe(false);
  });

  it("emits task_max_retries_exceeded when at retry limit", async () => {
    const retriedLog = Array(3).fill(null).map(() => ({
      action: "retried" as const, by: GIT_EMAIL, at: new Date().toISOString(),
    }));
    const task = makeTask({ status: "in_progress", log: retriedLog });
    const wsRoot = makeWorkspace(task);
    mockExecSync();
    mockSpawnSync(0);

    const events: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result: { terminal_status: "blocked", blocked_reason: "max_turns_exceeded" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: "test",
      taskRepoUrl: "git@github.com:org/impl.git",
      taskBaseBranch: "main",
      githubToken: "ghp_test",
      gitAuthorEmail: GIT_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e["type"] === "task_max_retries_exceeded")).toBe(true);
    // Falls through to blocked handling
    expect(events.some((e) => e["type"] === "mutate_task_yaml_failed" || e["type"] === "append_log_failed" || true)).toBe(true);
  });
});

