/**
 * Review result dispatcher — skeleton.
 *
 * Routes the reviewer agent result to the appropriate side-effect handler:
 *   passed          → Auto-Done Writer (T5): write done + auto-ready cascade
 *   change_requested → Mutate task to change_requested (T4)
 *   escalate        → Escalation Handler (T6): Slack + blocked
 */

import { taskBranchName } from "../paths.js";
import { appendLogEntry } from "./append-log.js";
import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";

export interface ReviewResult {
  terminal_status: "passed" | "change_requested" | "escalate";
  verdict?: string;
  confidence?: string;
  notes?: string;
  review_url?: string;
}

export interface DispatchReviewResultOpts {
  result: ReviewResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

export async function dispatchReviewResult(opts: DispatchReviewResultOpts): Promise<void> {
  const { result, workspaceRoot, featureId, taskId, gitAuthorEmail, gitAuthorName, sshKeyPath, emit } = opts;
  const taskBranch = taskBranchName(featureId, taskId);

  try {
    switch (result.terminal_status) {
      case "passed": {
        emit({ type: "review_passed", task_id: taskId, feature_id: featureId, verdict: result.verdict, notes: result.notes, note: "auto-done writer stub — T5 fills this" });
        break;
      }
      case "change_requested": {
        const err = mutateTaskYamlDirect({ workspaceRoot, featureId, taskId, taskBranch, newStatus: "change_requested", gitAuthorEmail, gitAuthorName, sshKeyPath });
        if (err) {
          emit({ type: "review_change_requested_mutate_failed", task_id: taskId, feature_id: featureId, details: err });
          return;
        }
        const logErr = appendLogEntry({
          workspaceRoot, featureId, taskId, taskBranch,
          entry: {
            action: "change_requested", by: gitAuthorEmail,
            note: result.review_url ? `REQUEST_CHANGES posted: ${result.review_url}` : "Reviewer requested changes.",
            ...(result.review_url ? { review_url: result.review_url } : {}),
          },
          gitAuthorEmail, gitAuthorName, sshKeyPath,
        });
        if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
        emit({ type: "review_change_requested", task_id: taskId, feature_id: featureId, review_url: result.review_url });
        break;
      }
      case "escalate": {
        emit({ type: "review_escalate", task_id: taskId, feature_id: featureId, notes: result.notes, note: "escalation handler stub — T6 fills this" });
        break;
      }
      default: {
        emit({ type: "review_result_unknown_status", task_id: taskId, feature_id: featureId, terminal_status: (result as ReviewResult).terminal_status });
      }
    }
  } catch (e) {
    emit({ type: "review_dispatch_result_error", task_id: taskId, feature_id: featureId, details: String(e) });
  }
}

