1	/**
2	 * Orchestrator side-effect dispatcher.
3	 *
4	 * Translates an ExecutorResult into the correct set of side effects.
5	 * Max-turns retry: blocked + blocked_reason.startsWith("max_turns") → reset to "ready"
6	 * up to EXECUTOR_MAX_RETRIES times before permanently blocking.
7	 */
8	
9	import { readFileSync } from "node:fs";
10	import { parse as parseYaml } from "yaml";
11	import type { ExecutorResult } from "@workflow/runtime-abi";
12	import type { Task, TaskLogEntry } from "../types/task.js";
13	import { taskYamlAbsPath } from "../paths.js";
14	import { mutateTaskYaml } from "./mutate-task-yaml.js";
15	import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";
16	import { appendLogEntry } from "./append-log.js";
17	
18	export interface DispatchExecutorResultOpts {
19	  result: ExecutorResult;
20	  workspaceRoot: string;
21	  featureId: string;
22	  taskId: string;
23	  taskBranch: string;
24	  taskTitle: string;
25	  taskRepoUrl: string;
26	  taskBaseBranch: string;
27	  githubToken: string;
28	  gitAuthorEmail: string;
29	  gitAuthorName?: string;
30	  sshKeyPath?: string;
31	  emit: (event: Record<string, unknown>) => void;
32	}
33	
34	export async function dispatchExecutorResult(opts: DispatchExecutorResultOpts): Promise<void> {
35	  const { result, workspaceRoot, featureId, taskId, taskBranch, gitAuthorEmail, gitAuthorName, sshKeyPath, emit } = opts;
36	
37	  const EXECUTOR_MAX_RETRIES = Number(process.env.EXECUTOR_MAX_RETRIES ?? "3");
38	
39	  if (
40	    result.terminal_status === "blocked" &&
41	    typeof result.blocked_reason === "string" &&
42	    result.blocked_reason.startsWith("max_turns")
43	  ) {
44	    let task: Task | undefined;
45	    try {
46	      task = parseYaml(readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8")) as Task;
47	    } catch { /* fall through to blocked handling */ }
48	
49	    if (task !== undefined) {
50	      const retriedCount = (task.log ?? []).filter((e) => e.action === "retried").length;
51	
52	      if (retriedCount < EXECUTOR_MAX_RETRIES) {
53	        const logErr = appendLogEntry({
54	          workspaceRoot, featureId, taskId, taskBranch,
55	          entry: {
56	            action: "retried", by: gitAuthorEmail,
57	            note: `max_turns retry ${retriedCount + 1}/${EXECUTOR_MAX_RETRIES}`,
58	            ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
59	            ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
60	          },
61	          gitAuthorEmail, gitAuthorName, sshKeyPath,
62	        });
63	        if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
64	
65	        const mutateErr = mutateTaskYamlDirect({ workspaceRoot, featureId, taskId, taskBranch, newStatus: "ready", gitAuthorEmail, gitAuthorName, sshKeyPath });
66	        if (!mutateErr) {
67	          emit({ type: "task_retried", task_id: taskId, feature_id: featureId, attempt: retriedCount + 1, max: EXECUTOR_MAX_RETRIES });
68	          return;
69	        }
70	        emit({ type: "retry_reset_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
71	      } else {
72	        emit({ type: "task_max_retries_exceeded", task_id: taskId, feature_id: featureId, retried_count: retriedCount });
73	      }
74	    }
75	  }
76	
77	  const prUrl = result.pr_url;
78	
79	  if (result.terminal_status === "in_review") {
80	    if (prUrl) emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
81	    const mutateErr = mutateTaskYaml({ workspaceRoot, featureId, taskId, taskBranch, result, prUrl, gitAuthorEmail, gitAuthorName, sshKeyPath });
82	    if (mutateErr) {
83	      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
84	      throw new Error(mutateErr);
85	    }
86	    const entry: Omit<TaskLogEntry, "at"> = {
87	      action: "run_completed", by: gitAuthorEmail,
88	      note: prUrl ? `Implementation PR: ${prUrl}` : "Implementation complete.",
89	      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
90	      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
91	    };
92	    const logErr = appendLogEntry({ workspaceRoot, featureId, taskId, taskBranch, entry, gitAuthorEmail, gitAuthorName, sshKeyPath });
93	    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
94	  } else {
95	    if (prUrl) emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
96	    const mutateErr = mutateTaskYaml({ workspaceRoot, featureId, taskId, taskBranch, result, prUrl, gitAuthorEmail, gitAuthorName, sshKeyPath });
97	    if (mutateErr) {
98	      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
99	      throw new Error(mutateErr);
100	    }
101	    const entry: Omit<TaskLogEntry, "at"> = {
102	      action: "blocked", by: gitAuthorEmail,
103	      note: result.blocked_reason ?? "executor returned non-in_review status",
104	      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
105	      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
106	    };
107	    const logErr = appendLogEntry({ workspaceRoot, featureId, taskId, taskBranch, entry, gitAuthorEmail, gitAuthorName, sshKeyPath });
108	    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
109	  }
110	}
