131	): TaskContext {
132	  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
133	  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
134	  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
