136	
137	  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
138	  let taskModelOverrides = {};
139	  try {
140	    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
