188	  // Anchor to the task branch tip before reading/writing — same pattern as
189	  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
190	  // the task branch, but an explicit anchor makes this function self-contained.
191	  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
192	  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);
