204	}
205	
206	// ── Main ──────────────────────────────────────────────────────────────────────
207	
208	async function main(): Promise<number> {
209	  let agentYamlPath: string;
210	  let workflowLocalPath: string;
211	  let workspacesRoot: string;
212	  let gitAuthorEmail: string;
213	
214	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
215	  const bootstrapEmit = (event: Record<string, unknown>) => {
