232	  const sshKeyPath = sshResolution.sshKeyPath;
233	
234	  // ── Create the runtime profile ────────────────────────────────────────────────
235	  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
236	  // new infra is added without core changes.
237	  //   local-subprocess (default) — executor + in-process broker in one container
238	  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
239	  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
240	  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
241	    runtimeProfile === "local-docker"
242	      ? createLocalDockerProfile({
243	          gitAuthorEmail,
244	          gitAuthorName,
245	          sshKeyPath,
246	          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
247	        })
248	      : createLocalSubprocessProfile({
