1	/**
2	 * Orchestrator main entry point.
3	 *
4	 * Lifecycle:
5	 *   bootstrap (once) → polling loop:
6	 *     pull workspaces → eligibility → claim → briefing → adapter.run →
7	 *     side-effects → sleep → repeat
8	 *
9	 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
10	 *   0   → single-shot mode: one cycle then exit
11	 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
12	 *
13	 * Exit codes:
14	 *   0  normal exit
15	 *   2  agent.yaml invalid
16	 *   3  git clone/pull failed (bootstrap only)
17	 *   4  unexpected fatal error
18	 */
19	
20	import { existsSync, readFileSync, writeFileSync } from "node:fs";
21	import { join } from "node:path";
22	import { tmpdir } from "node:os";
23	import { execSync, spawn } from "node:child_process";
24	import { randomUUID } from "node:crypto";
25	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
26	import { runBootstrap } from "./bootstrap/bootstrap.js";
27	import { resolveSSHKey } from "./resolve-ssh-key.js";
28	import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName, featureBranchName } from "./paths.js";
29	import { runFeatureBranchLifecycle } from "./feature-branch/lifecycle-manager.js";
30	import { findEligibleTasks } from "./eligibility/match.js";
31	import { claimTask } from "./claim/claim-task.js";
32	import { openWorkspacePr } from "./claim/open-workspace-pr.js";
33	import type { Task, TaskLogEntry } from "./types/task.js";
34	import { generateBriefing } from "./briefing/agent-context.js";
35	import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
36	import { resolveModel } from "./config/resolve-model-policy.js";
37	import { parseModelOverrides } from "./config/parse-model-overrides.js";
38	import {
39	  resolveRepoLocalPath,
40	  resolveRepoBaseBranch,
41	  resolveRepoGitUrl,
42	  loadWorkspaceModelPolicy,
43	  parseManagementRepoCoords,
44	} from "./config/workspace-config.js";
45	import { pullWorkspaces } from "./poll/pull-workspaces.js";
46	import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
47	import { runReapLoop } from "./poll/reap-loop.js";
48	import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
49	import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
50	import { handleDraftReviews } from "./pr-response/dispatch-draft-review.js";
51	import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
52	import type { ExecutorPortInput } from "@workflow/runtime-abi";
53	import { buildGitEnv } from "./git-env.js";
54	import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
55	import { createLocalSubprocessProfile } from "./profiles/local-subprocess.js";
56	import { createLocalDockerProfile } from "./profiles/local-docker.js";
57	import type { RuntimePorts } from "./runtime-ports.js";
58	import { SubProcessAdapter } from "./adapters/executor/subprocess.js";
59	import { InMemoryBrokerAdapter } from "./adapters/broker/in-memory.js";
60	
61	// ── Helpers ───────────────────────────────────────────────────────────────────
62	
63	/**
64	 * Returns an invokeClaudeForResolution function that pins Claude to a specific model.
65	 * Passed to all conflict-resolution handlers so they respect workspace model_policy
66	 * instead of defaulting to whatever the Claude CLI ships with.
67	 */
68	function makeConflictResolver(
69	  model: string,
70	  maxTurns = 10,
71	): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
72	  return (prompt, cwd, env) =>
73	    new Promise((resolve) => {
74	      const child = spawn(
75	        "claude",
76	        [
77	          "-p", prompt,
78	          "--model", model,
79	          "--max-turns", String(maxTurns),
80	          "--output-format", "stream-json",
81	          "--verbose",
82	          "--dangerously-skip-permissions",
83	        ],
84	        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
85	      );
86	      child.stdout.pipe(process.stdout);
87	      child.stderr.pipe(process.stderr);
88	      child.on("close", (code) => resolve(code === 0));
89	      child.on("error", () => resolve(false));
90	    });
91	}
92	
93	function requireEnv(name: string): string {
94	  const val = process.env[name];
95	  if (!val) throw new Error(`Required environment variable ${name} is not set`);
96	  return val;
97	}
98	
99	function extractRepoName(url: string): string {
100	  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
101	  return match?.[1] ?? url;
102	}
103	
104	/** Emit a structured JSON event via the profile's EventEmitterPort. */
105	function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
106	  return (event: Record<string, unknown>) => {
107	    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
108	    ports.emitter.emit(type ?? "event", data);
109	  };
110	}
111	
112	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
113	  const task = parseYaml(
114	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
115	  ) as { repo: string };
116	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
117	  return task.repo;
118	}
119	
120	interface TaskContext {
121	  taskRepoRoot: string;
122	  taskRepoUrl: string;
123	  taskBaseBranch: string;
124	  implementationModel: string;
125	}
126	
127	function resolveTaskContext(
128	  workspaceLocalPath: string,
129	  featureId: string,
130	  task: Task,
131	): TaskContext {
132	  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
133	  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
134	  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
135	  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
136	
137	  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
138	  let taskModelOverrides = {};
139	  try {
140	    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
141	  } catch { /* non-fatal */ }
142	
143	  const implementationModel = resolveModel(
144	    workspaceModelPolicy,
145	    taskModelOverrides,
146	    "implementation",
147	    task.id,
148	  );
149	
150	  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
151	}
152	
153	/**
154	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
155	 * Commits and pushes to the task branch. Throws on error.
156	 */
157	function writeRagPreFlight(
158	  workspaceRoot: string,
159	  featureId: string,
160	  taskId: string,
161	  taskBranch: string,
162	  gitAuthorEmail: string,
163	  gitAuthorName: string,
164	  sshKeyPath: string | undefined,
165	  ragPreFlight: { query: string; injected: boolean; summary: string },
166	): void {
167	  const now = new Date().toISOString();
168	  const entry: TaskLogEntry = {
169	    action: "rag_pre_flight",
170	    by: gitAuthorEmail,
171	    at: now,
172	    rag_context_injected: ragPreFlight.injected,
173	    rag_summary: ragPreFlight.summary,
174	    rag_query: ragPreFlight.query,
175	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
176	  };
177	
178	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
179	  const relPath = taskYamlRelPath(featureId, taskId);
180	  const gitOpts = {
181	    cwd: workspaceRoot,
182	    encoding: "utf-8" as const,
183	    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
184	    timeout: 30_000,
185	    stdio: "pipe" as const,
186	  };
187	
188	  // Anchor to the task branch tip before reading/writing — same pattern as
189	  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
190	  // the task branch, but an explicit anchor makes this function self-contained.
191	  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
192	  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);
193	
194	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
195	  task.log.push(entry);
196	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
197	
198	  execSync(`git add "${relPath}"`, gitOpts);
199	  execSync(
200	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
201	    gitOpts,
202	  );
203	  execSync(`git push origin "${taskBranch}"`, gitOpts);
204	}
205	
206	// ── Main ──────────────────────────────────────────────────────────────────────
207	
208	async function main(): Promise<number> {
209	  let agentYamlPath: string;
210	  let workflowLocalPath: string;
211	  let workspacesRoot: string;
212	  let gitAuthorEmail: string;
213	
214	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
215	  const bootstrapEmit = (event: Record<string, unknown>) => {
216	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
217	  };
218	
219	  try {
220	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
221	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
222	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
223	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
224	  } catch (e) {
225	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
226	    return 4;
227	  }
228	
229	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
230	
231	  const sshResolution = resolveSSHKey(process.env);
232	  const sshKeyPath = sshResolution.sshKeyPath;
233	
234	  // ── Create the runtime profile ────────────────────────────────────────────────
235	  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
236	  // new infra is added without core changes.
237	  //   local-subprocess (default) — executor + in-process broker in one container
238	  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
239	  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
240	  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
241	    runtimeProfile === "local-docker"
242	      ? createLocalDockerProfile({
243	          gitAuthorEmail,
244	          gitAuthorName,
245	          sshKeyPath,
246	          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
247	        })
248	      : createLocalSubprocessProfile({
249	          gitAuthorEmail,
250	          gitAuthorName,
251	          sshKeyPath,
252	        });
253	
254	  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
255	  const brokerPort = await ports.broker.start();
256	
257	  const emit = makeEmit(ports);
258	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
259	
260	  if (sshResolution.warned) {
261	    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
262	  }
263	
264	  const bootstrapResult = await runBootstrap({
265	    agentYamlPath,
266	    workflowLocalPath,
267	    workflowUrl: process.env.WORKFLOW_URL,
268	    workspacesRoot,
269	    sshKeyPath,
270	  });
271	
272	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
273	
274	  const config = bootstrapResult.config!;
275	  const githubToken = process.env.GITHUB_TOKEN ?? "";
276	  if (!githubToken) emit({ type: "warn_no_github_token" });
277	
278	  // ── Feature Branch Lifecycle Manager (T8) ────────────────────────────────────
279	  // Runs once at startup — creates or syncs feature/{featureId} on each watched
280	  // workspace before the main dispatch loop begins.
281	  for (const watchUrl of config.watches) {
282	    const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
283	    if (!existsSync(workspaceLocalPath)) continue;
284	    try {
285	      const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
286	      runFeatureBranchLifecycle({
287	        workspaceRoot: workspaceLocalPath,
288	        baseBranch: mgmtCoords.baseBranch,
289	        gitAuthorEmail,
290	        gitAuthorName,
291	        sshKeyPath,
292	        emit,
293	      });
294	    } catch (e) {
295	      emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
296	    }
297	  }
298	
299	  let lastPrPollAt: number | null = null;
300	  // Local counter for local-docker mode — tracks how many executor containers are
301	  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
302	  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
303	  let dockerInFlight = 0;
304	
305	  async function runOneCycle(): Promise<CycleOutcome> {
306	    // In local-subprocess mode all repos share the same container filesystem.
307	    // If an executor is running, skip impl repo pulls — syncRepo would switch
308	    // the shared working tree to the base branch and hard-reset it, destroying
309	    // any uncommitted work the executor has in flight.
310	    const execInFlight =
311	      runtimeProfile === "local-subprocess"
312	        ? (ports.broker as InMemoryBrokerAdapter).registrySize() > 0
313	        : false;
314	
315	    const pullResults = pullWorkspaces({
316	      watchUrls: config.watches,
317	      sshKeyPath,
318	      workspacesRoot,
319	      workflowUrl: process.env.WORKFLOW_URL,
320	      workflowLocalPath,
321	      skipImplRepoPull: execInFlight,
322	      emit,
323	    });
324	
325	    const haltedUrls = new Set(
326	      pullResults
327	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
328	        .map((r) => r.url),
329	    );
330	
331	    let outcome: CycleOutcome = "idle";
332	    const pulledWorkspaceRoots: string[] = [];
333	
334	    // ── Subprocess concurrency guard + task dispatch ──────────────────────────
335	    // In local-subprocess mode all repos share the same container filesystem.
336	    // Two concurrent subprocesses can race on git checkouts in the same repo.
337	    // Wrap the dispatch loop in a labeled block so we can break out of it
338	    // (skipping to PR poll + reap) when a subprocess is already in-flight.
339	    dispatchBlock: {
340	      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
341	      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;
342	
343	      if (runtimeProfile === "local-subprocess") {
344	        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
345	        if (inFlight >= maxConcurrent) {
346	          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
347	          break dispatchBlock;
348	        }
349	      } else if (runtimeProfile === "local-docker") {
350	        if (dockerInFlight >= maxConcurrent) {
351	          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
352	          break dispatchBlock;
353	        }
354	      }
355	
356	    outerLoop:
357	    for (const watchUrl of config.watches) {
358	      if (haltedUrls.has(watchUrl)) continue;
359	
360	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
361	      pulledWorkspaceRoots.push(workspaceLocalPath);
362	
363	      if (!existsSync(workspaceLocalPath)) {
364	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
365	        continue;
366	      }
367	
368	      let eligibleTasks;
369	      try {
370	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
371	      } catch (e) {
372	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
373	        continue;
374	      }
375	
376	      if (eligibleTasks.length === 0) {
377	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
378	        continue;
379	      }
380	
381	      for (const { task, featureId } of eligibleTasks) {
382	        const claimResult = await claimTask({
383	          workspaceRoot: workspaceLocalPath,
384	          taskId: task.id,
385	          featureId,
386	          gitAuthorEmail,
387	          gitAuthorName,
388	          sshKeyPath,
389	          jitterMaxSeconds: config.jitter_max_seconds,
390	        });
391	
392	        const taskBranch = taskBranchName(featureId, task.id);
393	
394	        if (!claimResult.won) {
395	          if (claimResult.reason !== "branch_blocked_recovery") {
396	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
397	            continue;
398	          }
399	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
400	        } else {
401	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
402	        }
403	
404	        // ── Open management-repo PR ───────────────────────────────────────────
405	        if (githubToken) {
406	          try {
407	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
408	            await openWorkspacePr({
409	              workspaceRoot: workspaceLocalPath,
410	              featureId,
411	              taskId: task.id,
412	              branch: taskBranch,
413	              // Task PRs target the feature branch so all task changes collect
414	              // there before the Handoff Trigger merges to the base branch (T8).
415	              baseBranch: featureBranchName(featureId),
416	              githubToken,
417	              repoOwner: mgmtCoords.owner,
418	              repoName: mgmtCoords.repo,
419	              gitAuthorEmail,
420	              gitAuthorName,
421	              sshKeyPath,
422	            });
423	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
424	          } catch (e) {
425	            const stderr = (e as { stderr?: Buffer | string }).stderr;
426	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
427	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
428	          }
429	        }
430	
431	        // ── Resolve model + task repo ────────────────────────────────────────
432	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
433	          resolveTaskContext(workspaceLocalPath, featureId, task);
434	
435	        // ── RAG pre-flight ───────────────────────────────────────────────────
436	        const mcpRagUrl = process.env.MCP_RAG_URL;
437	        const workspaceYaml = parseYaml(
438	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
439	        ) as { workspace_id: string };
440	        const ragQuery = `${task.title} ${featureId}`;
441	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
442	
443	        try {
444	          writeRagPreFlight(
445	            workspaceLocalPath,
446	            featureId,
447	            task.id,
448	            taskBranch,
449	            gitAuthorEmail,
450	            gitAuthorName,
451	            sshKeyPath,
452	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
453	          );
454	        } catch (e) {
455	          const details = String(e);
456	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
457	          mutateTaskYaml({
458	            workspaceRoot: workspaceLocalPath,
459	            featureId,
460	            taskId: task.id,
461	            taskBranch,
462	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
463	            gitAuthorEmail,
464	            gitAuthorName,
465	            sshKeyPath,
466	          });
467	          continue;
468	        }
469	
470	        // ── Generate briefing ────────────────────────────────────────────────
471	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
472	        const baseContext = generateBriefing({
473	          taskId: task.id,
474	          featureId,
475	          taskTitle: task.title,
476	          taskBranch,
477	          taskRepo: task.repo,
478	          taskRepoRoot,
479	          workspaceRoot: workspaceLocalPath,
480	          gitAuthorEmail,
481	          gitAuthorName,
482	          implementationModel,
483	          resultPath,
484	        });
485	        const briefingContent = ragPreFlight.block
486	          ? `${baseContext}\n\n${ragPreFlight.block}`
487	          : baseContext;
488	
489	        // ── Write briefing via BriefingTransportPort ─────────────────────────
490	        // Use taskId as the briefing handle so the file path matches the
491	        // existing briefing-{taskId}/briefing.md convention.
492	        const briefingPath = await ports.briefing.put(task.id, briefingContent);
493	
494	        // ── Build ExecutorPortInput ──────────────────────────────────────────
495	        const nonce = randomUUID();
496	        const callbackUrl = ports.broker.getCallbackUrl() ?? "";
497	
498	        const execInput: ExecutorPortInput = {
499	          taskId: task.id,
500	          featureId,
501	          workspaceId: workspaceYaml.workspace_id,
502	          taskRepoUrl,
503	          taskRepoBranch: taskBranch,
504	          taskRepoPath: taskRepoRoot,
505	          briefingPath,
506	          resultPath,
507	          budgetTokens: config.budget.max_tokens_per_task,
508	          implementationModel,
509	          sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
510	          githubToken,
511	          callbackUrl,
512	          nonce,
513	        };
514	
515	        // ── Submit executor (async — T6) ─────────────────────────────────────
516	        // A fresh adapter is created per task to carry task-scoped extraEnv;
517	        // the profile's broker and other ports are reused.
518	        const taskExtraEnv: Record<string, string> = {
519	          WORKSPACE_ROOT: workspaceLocalPath,
520	          TASK_BRANCH: taskBranch,
521	          GIT_AUTHOR_EMAIL: gitAuthorEmail,
522	          GIT_AUTHOR_NAME: gitAuthorName,
523	          WORKFLOW_LOCAL_PATH: workflowLocalPath,
524	          MAX_TURNS: String(config.budget.max_iterations),
525	          LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
526	          ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
527	          ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
528	            ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
529	            : {}),
530	        };
531	        const perTaskExecutor =
532	          runtimeProfile === "local-docker"
533	            ? new (await import("./adapters/executor/docker-run.js")).DockerRunAdapter({
534	                broker: ports.broker,
535	                extraEnv: taskExtraEnv,
536	              })
537	            : new SubProcessAdapter({
538	                broker: ports.broker,
539	                extraEnv: taskExtraEnv,
540	              });
541	
542	        const execHandle = await perTaskExecutor.submit(execInput);
543	
544	        // Persist handle to task YAML for broker crash-recovery reconciliation.
545	        try {
546	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
547	        } catch (e) {
548	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
549	        }
550	
551	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
552	        if (runtimeProfile === "local-docker") dockerInFlight++;
553	        outcome = "ran_task";
554	        break outerLoop;
555	      }
556	    }
557	    } // end dispatchBlock
558	
559	    // ── In-review PR poll ─────────────────────────────────────────────────────
560	    // In local-subprocess mode the executor subprocess shares the same container
561	    // filesystem as the orchestrator. Both can race on `git rebase` in the same
562	    // repo — a second rebase operation fails with "rebase-merge directory already
563	    // exists". Re-check in-flight count here (not just in dispatchBlock) because
564	    // pulledWorkspaceRoots is already populated on the same cycle that dispatched
565	    // the executor; the dispatchBlock early-break only fires on *subsequent* cycles.
566	    const skipPrPoll =
567	      runtimeProfile === "local-subprocess" &&
568	      (ports.broker as InMemoryBrokerAdapter).registrySize() > 0;
569	    if (githubToken && !skipPrPoll) {
570	      const prPollIntervalMs =
571	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
572	      const now = Date.now();
573	
574	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
575	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
576	        try {
577	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
578	            workspaceRoots: pulledWorkspaceRoots,
579	            githubToken,
580	            emit,
581	          });
582	
583	          for (const wsRoot of pulledWorkspaceRoots) {
584	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
585	            if (wsResults.some((r) => r.mergeable === false)) {
586	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
587	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
588	              await handleMergeConflicts({
589	                prResults: wsResults,
590	                workspaceRoot: wsRoot,
591	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
592	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
593	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
594	                gitAuthorEmail,
595	                gitAuthorName,
596	                sshKeyPath,
597	                emit,
598	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
599	              });
600	            }
601	          }
602	
603	          for (const wsRoot of pulledWorkspaceRoots) {
604	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
605	            if (wsResults.some((r) => r.hasOpenComments === true)) {
606	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
607	              await handleDraftReviews({
608	                prResults: wsResults,
609	                workspaceRoot: wsRoot,
610	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
611	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
612	                resolveImplementationModel: (fId, tId) => {
613	                  try {
614	                    const tMdPath = join(wsRoot, "docs", "features", fId, "tasks.md");
615	                    const overrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), tId);
616	                    return resolveModel(wsModelPolicy, overrides, "implementation", tId);
617	                  } catch {
618	                    return resolveModel(wsModelPolicy, {}, "implementation", tId);
619	                  }
620	                },
621	                gitAuthorEmail,
622	                gitAuthorName,
623	                sshKeyPath,
624	                workflowLocalPath,
625	                maxTurns: config.budget.max_iterations,
626	                maxTokens: config.budget.max_tokens_per_task,
627	                logSinkEnabled: config.log_sink.enabled,
628	                workspaceId: (() => {
629	                  try {
630	                    return (parseYaml(readFileSync(workspaceYamlPath(wsRoot), "utf-8")) as { workspace_id: string }).workspace_id ?? "";
631	                  } catch { return ""; }
632	                })(),
633	                githubToken,
634	                resolveImplRepoUrl: (repoId) => resolveRepoGitUrl(wsRoot, repoId),
635	                broker: ports.broker,
636	                callbackUrl: ports.broker.getCallbackUrl() ?? "",
637	                emit,
638	              });
639	            }
640	          }
641	
642	          for (const wsRoot of pulledWorkspaceRoots) {
643	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
644	            if (wsResults.some((r) => r.merged === true)) {
645	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
646	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
647	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
648	              await handleMergedPrs({
649	                prResults: wsResults,
650	                workspaceRoot: wsRoot,
651	                mgmtRepoOwner: mgmtCoords.owner,
652	                mgmtRepoName: mgmtCoords.repo,
653	                mgmtBaseBranch: mgmtCoords.baseBranch,
654	                githubToken,
655	                gitAuthorEmail,
656	                gitAuthorName,
657	                sshKeyPath,
658	                emit,
659	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
660	              });
661	            }
662	          }
663	
664	          for (const wsRoot of pulledWorkspaceRoots) {
665	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
666	            if (wsRecoveries.length > 0) {
667	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
668	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
669	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
670	              await handleWorkspacePrRecoveries({
671	                recoveries: wsRecoveries,
672	                mgmtRepoOwner: mgmtCoords.owner,
673	                mgmtRepoName: mgmtCoords.repo,
674	                mgmtBaseBranch: mgmtCoords.baseBranch,
675	                githubToken,
676	                gitAuthorEmail,
677	                gitAuthorName,
678	                sshKeyPath,
679	                emit,
680	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
681	              });
682	            }
683	          }
684	        } catch (e) {
685	          emit({ type: "in_review_poll_error", details: String(e) });
686	        }
687	      }
688	    }
689	
690	    // ── Shared reap loop ──────────────────────────────────────────────────────
691	    // Drain completions posted by in-flight executors this cycle (and any
692	    // leftovers from previous cycles). Routes by handle.kind → dispatcher.
693	    try {
694	      const reapResult = await runReapLoop({
695	        broker: ports.broker,
696	        workspaceRoots: pulledWorkspaceRoots,
697	        gitAuthorEmail,
698	        gitAuthorName,
699	        sshKeyPath,
700	        githubToken,
701	        emit,
702	      });
703	      if (reapResult.dispatched > 0) {
704	        if (runtimeProfile === "local-docker") {
705	          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
706	        }
707	        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
708	        if (outcome === "idle") outcome = "ran_task";
709	      }
710	    } catch (e) {
711	      emit({ type: "reap_loop_error", details: String(e) });
712	    }
713	
714	    return outcome;
715	  }
716	
717	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
718	  return 0;
719	}
720	
721	main()
722	  .then((code) => process.exit(code))
723	  .catch((e) => {
724	    try {
725	      console.log(JSON.stringify({
726	        type: "fatal_error",
727	        details: (e as Error).message ?? String(e),
728	        at: new Date().toISOString(),
729	      }));
730	    } catch { /* last resort */ }
731	    process.exit(4);
732	  });
733

