describe("checkInReviewPrs — feature branch lookup (Option C)", () => {
  it("uses feature branch YAML when main shows ready but branch shows in_review", async () => {
    const mainTask = makeTask({ status: "ready", pr: { url: null, status: null } });
    const wsRoot = makeWorkspaceWithTask(mainTask);
    const branchTask = makeTask({ status: "in_review", pr: { url: SAMPLE_PR_URL, status: "open" } });

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(branchTask))
      .mockReturnValueOnce(mockGraphQL({ mergeable: "CONFLICTING" }));

    const { prResults: results } = await checkInReviewPrs({ workspaceRoots: [wsRoot], githubToken: GITHUB_TOKEN, emit: () => {} });

    expect(results).toHaveLength(1);
    expect(results[0].mergeable).toBe(false);
    expect(results[0].taskId).toBe(TASK_ID);
  });

  it("verifies git show is called with the correct branch ref", async () => {
    const task = makeTask({ status: "ready" });
    const wsRoot = makeWorkspaceWithTask(task);
    vi.mocked(spawnSync).mockReturnValueOnce(mockGitShowNotFound());

    await checkInReviewPrs({ workspaceRoots: [wsRoot], githubToken: GITHUB_TOKEN, emit: () => {} });

    const [cmd, args] = vi.mocked(spawnSync).mock.calls[0];
    const argsArr = args as string[];
    expect(cmd).toBe("git");
    expect(argsArr).toContain("show");
    expect(argsArr.some((a) => a.includes(`feature/${FEATURE_ID}-${TASK_ID}`))).toBe(true);
  });
});

