    const wsRoot = makeWorkspaceWithTask(task);

    const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
      workspaceRoots: [wsRoot],
      githubToken: GITHUB_TOKEN,
      emit: () => {},
    });

    expect(prResults).toHaveLength(0);
    expect(workspacePrRecoveries).toHaveLength(0);
    expect(vi.mocked(spawnSync)).not.toHaveBeenCalled();
  });

  it("does not flag a done branch task with no workspace_pr as a recovery candidate", async () => {
    const mainTask = makeTask({ status: "in_review" });
    const branchTask = makeTask({ status: "done", workspace_pr: null });
    const wsRoot = makeWorkspaceWithTask(mainTask);
    vi.mocked(spawnSync).mockReturnValueOnce(mockGitShowTask(branchTask));

    const { workspacePrRecoveries } = await checkInReviewPrs({
      workspaceRoots: [wsRoot],
      githubToken: GITHUB_TOKEN,
      emit: () => {},
    });

    expect(workspacePrRecoveries).toHaveLength(0);
  });
});

  return {
