import subprocess
import os
import sys

REPO = "/agent/data/agent-workflow"
BRANCH = "feature/autonomous-task-orchestrator-T2"
AUTHOR_EMAIL = "pentative@gmail.com"
AUTHOR_NAME = "Agent 2"

# ── File contents ──────────────────────────────────────────────────────────────

MUTATE_TASK_YAML_DIRECT = '''/**
 * Direct task YAML mutation for arbitrary TaskStatus values.
 *
 * Unlike mutateTaskYaml (which translates ExecutorResult), this helper sets
 * an explicit target status — used for orchestrator-driven transitions such as
 * max-turns retry (blocked → ready) and review result (in_review → change_requested).
 *
 * Pattern: git fetch/checkout task branch, read YAML, set status + optional log
 * entry, write YAML, git add/commit, spawnSync push.
 * Non-throwing: returns an error string on failure.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task, TaskStatus, TaskLogEntry } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface MutateTaskYamlDirectOpts {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  status: TaskStatus;
  /** Optional log entry appended in the same commit as the status change. */
  logEntry?: Omit<TaskLogEntry, "at"> & { at?: string };
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  /** Commit message. Defaults to "chore(<taskId>): status → <status>". */
  commitMessage?: string;
}

export function mutateTaskYamlDirect(opts: MutateTaskYamlDirectOpts): string | undefined {
  const {
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    status,
    logEntry,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    commitMessage,
  } = opts;

  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const msg = commitMessage ?? `chore(${taskId}): status → ${status}`;

  try {
    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" checkout -- .`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git fetch/checkout task branch failed: ${String(e)}`;
  }

  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return `failed to read task YAML: ${String(e)}`;
  }

  const now = new Date().toISOString();
  task.status = status;
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;

  if (logEntry) {
    const at = logEntry.at ?? now;
    task.log.push({ ...logEntry, at } as TaskLogEntry);
  }

  try {
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  } catch (e) {
    return `failed to write task YAML: ${String(e)}`;
  }

  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" commit -m "${msg}"`, { env, stdio: "pipe" });
  } catch (e) {
    return `git add/commit failed: ${String(e)}`;
  }

  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
