write_file("runtime/orchestrator/src/side-effects/dispatch-review-result.ts", r'''/**
 * Dispatch handler for reviewer-executor completions (handle.kind = "review").
 *
 * Routes by ReviewerResult.terminal_status:
 *   passed           → emit review_passed; TODO(T5): auto-merge + mark done
 *   change_requested → mutate task YAML to change_requested + log entry
 *   escalate         → emit review_escalate; TODO(T6): human escalation
 *   unknown          → emit review_result_unknown_status (no-op)
 */

import type { ReviewerResult } from "@workflow/runtime-abi";
import { taskBranchName } from "../paths.js";
import { mutateTaskYamlDirect } from "./mutate-task-yaml-direct.js";

export type ReviewResult = ReviewerResult;

export interface DispatchReviewResultOpts {
  result: ReviewResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

export async function dispatchReviewResult(opts: DispatchReviewResultOpts): Promise<void> {
  const {
    result,
    workspaceRoot,
    featureId,
    taskId,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    emit,
  } = opts;

  const taskBranch = taskBranchName(featureId, taskId);

  switch (result.terminal_status) {
    case "passed":
      emit({
        type: "review_passed",
        task_id: taskId,
        feature_id: featureId,
        verdict: result.verdict,
        confidence: result.confidence,
        notes: result.notes,
        review_url: result.review_url,
      });
      break;

    case "change_requested": {
      const mutateErr = mutateTaskYamlDirect({
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        status: "change_requested",
        logEntry: {
          action: "done",
          by: gitAuthorEmail,
          note: result.notes ?? "Reviewer requested changes.",
        },
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        commitMessage: `chore(${taskId}): reviewer → change_requested`,
      });
      if (mutateErr) {
        emit({ type: "review_mutate_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
        throw new Error(mutateErr);
      }
      emit({
        type: "review_change_requested",
        task_id: taskId,
        feature_id: featureId,
        notes: result.notes,
        review_url: result.review_url,
      });
      break;
    }

    case "escalate":
      emit({
        type: "review_escalate",
        task_id: taskId,
        feature_id: featureId,
        notes: result.notes,
        review_url: result.review_url,
      });
      break;

    default:
      emit({
        type: "review_result_unknown_status",
        task_id: taskId,
        feature_id: featureId,
        status: (result as { terminal_status: string }).terminal_status,
      });
  }
}
''')
