186	// ── Public API ────────────────────────────────────────────────────────────────
187	
188	/**
189	 * Scan all watched workspaces for `in_review` tasks whose PR URL is set,
190	 * then call the GitHub API for each to get current mergeability and draft state.
191	 *
192	 * Also detects `done` tasks that are on a feature branch but whose workspace PR
193	 * has not yet been merged, returning them as `workspacePrRecoveries` so the
194	 * main loop can retry the merge.
195	 *
196	 * Pure read — no task YAML mutations.
197	 */
198	export async function checkInReviewPrs(
199	  opts: CheckInReviewPrsOptions,
200	): Promise<CheckInReviewResult> {
201	  const { workspaceRoots, githubToken, emit } = opts;
202	  const prResults: PrStatusResult[] = [];
203	  const workspacePrRecoveries: WorkspacePrRecovery[] = [];
204	
205	  emit({ type: "in_review_poll_start", workspace_count: workspaceRoots.length });
206	
207	  for (const workspaceRoot of workspaceRoots) {
208	    const docsPath = featuresRoot(workspaceRoot);
209	    if (!existsSync(docsPath)) continue;
210	
211	    let featureDirs: string[];
212	    try {
213	      featureDirs = readdirSync(docsPath, { withFileTypes: true })
214	        .filter((e) => e.isDirectory())
215	        .map((e) => e.name);
216	    } catch {
217	      continue;
218	    }
219	
220	    for (const featureId of featureDirs) {
221	      const tasksDir = join(docsPath, featureId, TASKS_DIR);
222	      if (!existsSync(tasksDir)) continue;
223	
224	      let taskFiles: string[];
225	      try {
226	        taskFiles = readdirSync(tasksDir).filter((f) =>
227	          /^T\d+\.yaml$/.test(f),
228	        );
229	      } catch {
230	        continue;
231	      }
232	
233	      for (const fileName of taskFiles) {
234	        let task: Task;
235	        try {
236	          task = parseYaml(
237	            readFileSync(join(tasksDir, fileName), "utf-8"),
238	          ) as Task;
239	        } catch {
240	          continue;
241	        }
242	
243	        // If the task is in-flight on main, the live state is on the feature branch.
244	        // If the branch doesn't exist yet, there's nothing to poll — skip.
245	        let readFromBranch = false;
246	        let branchMissing = false;
247	        if (!TERMINAL_STATUSES.has(task.status)) {
248	          const taskId = fileName.replace(/\.yaml$/, "");
249	          const branch = taskBranchName(featureId, taskId);
250	          const relPath = taskYamlRelPath(featureId, taskId);
251	          const branchTask = tryReadTaskFromBranch(workspaceRoot, branch, relPath);
252	          if (!branchTask) {
253	            // Branch missing. If the task is in_review with a pr.url set, the branch was
254	            // likely deleted after a manual workspace-PR squash-merge while an executor was
255	            // in-flight (skipPrPoll guard). Fall back to the main YAML so the implementation
256	            // PR can still be polled and handleMergedPrs can recreate the branch.
257	            if (task.status === "in_review" && task.pr?.url) {
258	              branchMissing = true;
259	              emit({
260	                type: "in_review_poll_branch_missing_fallback",
261	                task_id: taskId,
262	                feature_id: featureId,
263	                note: "feature branch gone — falling back to main YAML for impl PR poll",
264	              });
265	              // task stays as the main YAML; readFromBranch stays false.
266	            } else {
267	              emit({
268	                type: "in_review_poll_skip",
269	                task_id: taskId,
270	                feature_id: featureId,
271	                reason: "branch_not_found",
272	              });
273	              continue;
274	            }
275	          } else {
276	            task = branchTask;
277	            readFromBranch = true;
278	          }
279	        }
280	
281	        // Recovery: task is done on the feature branch but the workspace (management-repo)
282	        // PR hasn't been merged yet. Queue for retry rather than polling the impl PR.
283	        // Skip if workspace_pr.status is already "merged" — nothing left to do.
284	        if (readFromBranch && task.status === "done" && task.workspace_pr?.url &&
285	            task.workspace_pr.status !== "merged") {
286	          emit({
287	            type: "workspace_pr_recovery_candidate",
288	            task_id: task.id,
289	            feature_id: featureId,
290	            workspace_pr_url: task.workspace_pr.url,
291	          });
292	          workspacePrRecoveries.push({
293	            taskId: task.id,
294	            featureId,
295	            workspaceRoot,
296	            workspacePrUrl: task.workspace_pr.url,
297	          });
298	          continue;
299	        }
300	
301	        // Only poll in_review tasks with a PR URL set.
302	        if (task.status !== "in_review") continue;
303	        if (!task.pr?.url) {
304	          emit({
305	            type: "in_review_poll_skip",
306	            task_id: task.id,
307	            feature_id: featureId,
308	            reason: "no_pr_url",
309	          });
310	          continue;
311	        }
312	
313	        const coords = parsePrUrl(task.pr.url);
314	        if (!coords) {
315	          emit({
316	            type: "in_review_poll_error",
317	            task_id: task.id,
318	            feature_id: featureId,
319	            details: `Cannot parse PR URL: ${task.pr.url}`,
320	          });
321	          continue;
322	        }
323	
324	        emit({
325	          type: "in_review_poll_fetching",
326	          task_id: task.id,
327	          feature_id: featureId,
328	          pr_url: task.pr.url,
329	        });
330	
331	        try {
332	          const prStatus = fetchPrStatus(
333	            coords.owner,
334	            coords.repo,
335	            coords.pullNumber,
336	            githubToken,
337	          );
338	
339	          emit({
340	            type: "in_review_poll_result",
341	            task_id: task.id,
342	            feature_id: featureId,
343	            pr_url: task.pr.url,
344	            merged: prStatus.merged,
345	            draft: prStatus.draft,
346	            mergeable: prStatus.mergeable,
347	            has_open_comments: prStatus.hasOpenComments,
348	          });
349	
350	          prResults.push({
351	            taskId: task.id,
352	            featureId,
353	            workspaceRoot,
354	            mergeable: prStatus.mergeable,
355	            draft: prStatus.draft,
356	            merged: prStatus.merged,
357	            hasOpenComments: prStatus.hasOpenComments,
358	            ...(branchMissing ? { branchMissing: true } : {}),
359	          });
360	        } catch (e) {
361	          emit({
362	            type: "in_review_poll_error",
363	            task_id: task.id,
364	            feature_id: featureId,
365	            details: String(e),
366	          });
367	        }
368	      }
369	    }
370	  }
371	
372	  emit({
373	    type: "in_review_poll_done",
374	    polled: prResults.length,
375	    merged: prResults.filter((r) => r.merged).length,
376	    has_open_comments: prResults.filter((r) => r.hasOpenComments).length,
377	    conflicting: prResults.filter((r) => r.mergeable === false).length,
378	    workspace_pr_recoveries: workspacePrRecoveries.length,
379	  });
380	
381	  return { prResults, workspacePrRecoveries };
382	}

