 96	): { owner: string; repo: string; pullNumber: number } | null {
 97	  const match = /https?:\/\/github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(url);
 98	  if (!match) return null;
 99	  return {
100	    owner: match[1],
101	    repo: match[2],
102	    pullNumber: parseInt(match[3], 10),
103	  };
