 66	 * instead of defaulting to whatever the Claude CLI ships with.
 67	 */
 68	function makeConflictResolver(
 69	  model: string,
 70	  maxTurns = 10,
 71	): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
 72	  return (prompt, cwd, env) =>
 73	    new Promise((resolve) => {
 74	      const child = spawn(
 75	        "claude",
 76	        [
 77	          "-p", prompt,
 78	          "--model", model,
 79	          "--max-turns", String(maxTurns),
 80	          "--output-format", "stream-json",
 81	          "--verbose",
 82	          "--dangerously-skip-permissions",
 83	        ],
 84	        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
 85	      );
 86	      child.stdout.pipe(process.stdout);
 87	      child.stderr.pipe(process.stderr);
 88	      child.on("close", (code) => resolve(code === 0));
 89	      child.on("error", () => resolve(false));
 90	    });
 91	}
