206	// ── Main ──────────────────────────────────────────────────────────────────────
207	
208	async function main(): Promise<number> {
209	  let agentYamlPath: string;
210	  let workflowLocalPath: string;
211	  let workspacesRoot: string;
212	  let gitAuthorEmail: string;
213	
214	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
215	  const bootstrapEmit = (event: Record<string, unknown>) => {
216	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
217	  };
218	
219	  try {
220	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
221	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
222	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
223	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
224	  } catch (e) {
225	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
226	    return 4;
227	  }
228	
229	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
230	
231	  const sshResolution = resolveSSHKey(process.env);
232	  const sshKeyPath = sshResolution.sshKeyPath;
233	
234	  // ── Create the runtime profile ────────────────────────────────────────────────
235	  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
236	  // new infra is added without core changes.
237	  //   local-subprocess (default) — executor + in-process broker in one container
238	  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
239	  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
240	  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
241	    runtimeProfile === "local-docker"
242	      ? createLocalDockerProfile({
243	          gitAuthorEmail,
244	          gitAuthorName,
245	          sshKeyPath,
246	          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
247	        })
248	      : createLocalSubprocessProfile({
249	          gitAuthorEmail,
250	          gitAuthorName,
251	          sshKeyPath,
252	        });
253	
254	  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
255	  const brokerPort = await ports.broker.start();
256	
257	  const emit = makeEmit(ports);
258	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
259	
260	  if (sshResolution.warned) {
261	    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
262	  }
263	
264	  const bootstrapResult = await runBootstrap({
265	    agentYamlPath,
266	    workflowLocalPath,
267	    workflowUrl: process.env.WORKFLOW_URL,
268	    workspacesRoot,
269	    sshKeyPath,
270	  });
271	
272	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
273	
274	  const config = bootstrapResult.config!;
275	  const githubToken = process.env.GITHUB_TOKEN ?? "";
276	  if (!githubToken) emit({ type: "warn_no_github_token" });
277	
278	  // ── Feature Branch Lifecycle Manager (T8) ────────────────────────────────────
279	  // Runs once at startup — creates or syncs feature/{featureId} on each watched
280	  // workspace before the main dispatch loop begins.
281	  for (const watchUrl of config.watches) {
282	    const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
283	    if (!existsSync(workspaceLocalPath)) continue;
284	    try {
285	      const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
286	      runFeatureBranchLifecycle({
287	        workspaceRoot: workspaceLocalPath,
288	        baseBranch: mgmtCoords.baseBranch,
289	        gitAuthorEmail,
290	        gitAuthorName,
291	        sshKeyPath,
292	        emit,
293	      });
294	    } catch (e) {
295	      emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
296	    }
297	  }
298	
299	  let lastPrPollAt: number | null = null;
300	  // Local counter for local-docker mode — tracks how many executor containers are
301	  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
302	  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
303	  let dockerInFlight = 0;
304	
305	  async function runOneCycle(): Promise<CycleOutcome> {
306	    // In local-subprocess mode all repos share the same container filesystem.
307	    // If an executor is running, skip impl repo pulls — syncRepo would switch
308	    // the shared working tree to the base branch and hard-reset it, destroying
309	    // any uncommitted work the executor has in flight.
310	    const execInFlight =
311	      runtimeProfile === "local-subprocess"
312	        ? (ports.broker as InMemoryBrokerAdapter).registrySize() > 0
313	        : false;
314	
315	    const pullResults = pullWorkspaces({
316	      watchUrls: config.watches,
317	      sshKeyPath,
318	      workspacesRoot,
319	      workflowUrl: process.env.WORKFLOW_URL,
320	      workflowLocalPath,
321	      skipImplRepoPull: execInFlight,
322	      emit,
323	    });
324	
325	    const haltedUrls = new Set(
326	      pullResults
327	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
328	        .map((r) => r.url),
329	    );
330	
331	    let outcome: CycleOutcome = "idle";
332	    const pulledWorkspaceRoots: string[] = [];
333	
334	    // ── Subprocess concurrency guard + task dispatch ──────────────────────────
335	    // In local-subprocess mode all repos share the same container filesystem.
336	    // Two concurrent subprocesses can race on git checkouts in the same repo.
337	    // Wrap the dispatch loop in a labeled block so we can break out of it
338	    // (skipping to PR poll + reap) when a subprocess is already in-flight.
339	    dispatchBlock: {
340	      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
341	      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;
342	
343	      if (runtimeProfile === "local-subprocess") {
344	        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
345	        if (inFlight >= maxConcurrent) {
346	          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
347	          break dispatchBlock;
348	        }
349	      } else if (runtimeProfile === "local-docker") {
350	        if (dockerInFlight >= maxConcurrent) {
351	          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
352	          break dispatchBlock;
353	        }
354	      }
355	
356	    outerLoop:
357	    for (const watchUrl of config.watches) {
358	      if (haltedUrls.has(watchUrl)) continue;
359	
360	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
361	      pulledWorkspaceRoots.push(workspaceLocalPath);
362	
363	      if (!existsSync(workspaceLocalPath)) {
364	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
365	        continue;
366	      }
367	
368	      let eligibleTasks;
369	      try {
370	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
371	      } catch (e) {
372	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
373	        continue;
374	      }
375	
376	      if (eligibleTasks.length === 0) {
377	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
378	        continue;
379	      }
380	
381	      for (const { task, featureId } of eligibleTasks) {
382	        const claimResult = await claimTask({
383	          workspaceRoot: workspaceLocalPath,
384	          taskId: task.id,
385	          featureId,
386	          gitAuthorEmail,
387	          gitAuthorName,
388	          sshKeyPath,
389	          jitterMaxSeconds: config.jitter_max_seconds,
390	        });
391	
392	        const taskBranch = taskBranchName(featureId, task.id);
393	
394	        if (!claimResult.won) {
395	          if (claimResult.reason !== "branch_blocked_recovery") {
396	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
397	            continue;
398	          }
399	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
400	        } else {
401	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
402	        }
403	
404	        // ── Open management-repo PR ───────────────────────────────────────────
405	        if (githubToken) {
406	          try {
407	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
408	            await openWorkspacePr({
409	              workspaceRoot: workspaceLocalPath,
410	              featureId,
411	              taskId: task.id,
412	              branch: taskBranch,
413	              // Task PRs target the feature branch so all task changes collect
414	              // there before the Handoff Trigger merges to the base branch (T8).
415	              baseBranch: featureBranchName(featureId),
416	              githubToken,
417	              repoOwner: mgmtCoords.owner,
418	              repoName: mgmtCoords.repo,
419	              gitAuthorEmail,
420	              gitAuthorName,
421	              sshKeyPath,
422	            });
423	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
424	          } catch (e) {
425	            const stderr = (e as { stderr?: Buffer | string }).stderr;
426	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
427	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
428	          }
429	        }
430	
431	        // ── Resolve model + task repo ────────────────────────────────────────
432	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
433	          resolveTaskContext(workspaceLocalPath, featureId, task);
434	
435	        // ── RAG pre-flight ───────────────────────────────────────────────────
436	        const mcpRagUrl = process.env.MCP_RAG_URL;
437	        const workspaceYaml = parseYaml(
438	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
439	        ) as { workspace_id: string };
440	        const ragQuery = `${task.title} ${featureId}`;
441	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
442	
443	        try {
444	          writeRagPreFlight(
445	            workspaceLocalPath,
446	            featureId,
447	            task.id,
448	            taskBranch,
449	            gitAuthorEmail,
450	            gitAuthorName,
451	            sshKeyPath,
452	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
453	          );
454	        } catch (e) {
455	          const details = String(e);
456	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
457	          mutateTaskYaml({
458	            workspaceRoot: workspaceLocalPath,
459	            featureId,
460	            taskId: task.id,
461	            taskBranch,
462	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
463	            gitAuthorEmail,
464	            gitAuthorName,
465	            sshKeyPath,
466	          });
467	          continue;
468	        }
469	
470	        // ── Generate briefing ────────────────────────────────────────────────
