/**
 * Find all tasks eligible for a fix agent (status=change_requested with a PR URL).
 * Live state is read from the feature branch when available.
 */
export function findFixableTasks(
  agentConfig: AgentConfig,
  workspaceRoot: string,
): EligibleTask[] {
  const workspaceConfig = loadWorkspaceConfig(workspaceRoot);
  const managementRepoId = workspaceConfig.management_repo;
  const managementRepo = workspaceConfig.repos.find((r) => r.id === managementRepoId);
  if (!managementRepo) return [];

  const watchedUrls = new Set(agentConfig.watches);
  if (!watchedUrls.has(managementRepo.github)) return [];

  const allEntries = scanAllFeatures(workspaceRoot);
  const eligible: EligibleTask[] = [];

  for (const { task, featureId } of allEntries) {
    if (task.status !== "change_requested") continue;
    const branch = taskBranchName(featureId, task.id);
    const relPath = taskYamlRelPath(featureId, task.id);
    const liveTask = tryReadTaskFromBranch(workspaceRoot, branch, relPath) ?? task;
    if (liveTask.status !== "change_requested") continue;
    if (!liveTask.pr?.url) continue;
    eligible.push({ task: liveTask, featureId });
  }

  eligible.sort((a, b) => taskNumericId(a.task.id) - taskNumericId(b.task.id));
  return eligible;
}

